// The wac lexer, in wac. Port of compiler/wacLex.ts.
//
// Differences from the reference, both deliberate:
//
// A token holds a byte *span* into the source rather than its text. The reference
// stores `text: string`; spans are cheaper and are what real compilers keep. Three
// kinds have text that is computed rather than copied — string literals (the
// reference stores the unescaped value), character literals (stored as the decimal
// codepoint) and nothing else — so a consumer that wants the value calls
// `tokenString` or `tokenCodepoint` rather than reading the span directly.
//
// Columns count UTF-16 code units, not bytes, so that positions match the reference
// exactly on non-ASCII lines. `advance` does the accounting: a continuation byte
// adds nothing, a 4-byte sequence adds two (it is a surrogate pair in UTF-16), and
// everything else adds one.

import {
  kInt, kFloat, kString, kIdent, kEof,
  kImport, kExport, kStruct, kConst, kThis, kOverride,
  kIf, kElse, kWhile, kFor, kDo, kSwitch, kCase, kDefault,
  kBreak, kContinue, kReturn, kTrap, kTrue, kFalse, kNull,
  kIs, kNot, kAs, kVoid, kFn, kEnum, kMatch,
  kAsBang, kAsTilde, kAsAt,
  kPlus, kMinus, kStar, kSlash, kPercent, kAssign, kEq, kNe,
  kLt, kLe, kGt, kGe, kAndAnd, kOrOr, kBang, kAnd, kOr, kCaret, kTilde,
  kShl, kShr, kShrU,
  kPlusEq, kMinusEq, kStarEq, kSlashEq, kPercentEq,
  kAndEq, kOrEq, kCaretEq, kShlEq, kShrEq, kShrUEq,
  kInc, kDec,
  kLparen, kRparen, kLbrace, kRbrace, kLbrack, kRbrack,
  kSemi, kColon, kComma, kDot, kQuestion, kAt,
} from "./kinds.wac";

// ── Output ────────────────────────────────────────────────────────────────────
//
// Tokens come back as a flat i32 array of (kind, start, len, line, col) and errors
// as (code, line, col). Not because that is nicer — a `Token[]` would be — but
// because wac has no generics, so a growable array of structs means writing a third
// container by hand after gzip's `Buf` and json's. Flat also means no growth at
// all: a source of n bytes cannot produce more than n tokens, so the arrays are
// sized once from the input.

export i32 tokenStride() { return 5; }   // kind, start, len, line, col
export i32 errorStride() { return 3; }   // code, line, col

export struct Lexed {
  i32[] tokens;
  i32 tokenCount;      // tokens, not i32s
  i32[] errors;
  i32 errorCount;
}

// Error codes rather than messages: a message would mean building a string per
// error, and the consumer renders these anyway.
export i32 errUnexpectedChar()      { return 1; }
export i32 errUnterminatedString()  { return 2; }
export i32 errUnknownEscape()       { return 3; }
export i32 errUnterminatedComment() { return 4; }
export i32 errUnterminatedChar()    { return 5; }
export i32 errEmptyChar()           { return 6; }
export i32 errCharTooLong()         { return 7; }

// ── Character classification ──────────────────────────────────────────────────
//
// Bytes, not codepoints: every character wac's grammar cares about is ASCII, and a
// non-ASCII byte can only appear inside a string, a comment or an error.

bool isDigit(i32 c)  { return c >= '0' && c <= '9'; }
bool isHexDigit(i32 c) {
  return isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}
bool isIdentStart(i32 c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_';
}
bool isIdentPart(i32 c) { return isIdentStart(c) || isDigit(c); }
bool isSpace(i32 c) { return c == ' ' || c == '\t' || c == '\r' || c == '\n'; }

// Keyword matching by packing the span into an i64 and comparing integers.
//
// Comparing against a `string` literal is now possible — `string.toBytes` landed
// mid-write — but it allocates a byte array per candidate, and this runs once per
// identifier in the source. Packing is allocation free and every wac keyword is
// 8 bytes or fewer, so each fits an i64 exactly.
//
// (Indexing a string still yields a one-character *string*, not a byte, so the
// direct `src[i] != want[i]` comparison remains unavailable.)

i64 packSpan(u8[] src, i32 start, i32 len) {
  i64 v = 0 as i64;
  for (i32 i = 0; i < len; i++) {
    v = (v << 8) | (src[start + i] as i64);
  }
  return v;
}

i64 p2(i32 a, i32 b) { return ((a as i64) << 8) | (b as i64); }
i64 p3(i32 a, i32 b, i32 c) { return (p2(a, b) << 8) | (c as i64); }
i64 p4(i32 a, i32 b, i32 c, i32 d) { return (p3(a, b, c) << 8) | (d as i64); }
i64 p5(i32 a, i32 b, i32 c, i32 d, i32 e) { return (p4(a, b, c, d) << 8) | (e as i64); }
i64 p6(i32 a, i32 b, i32 c, i32 d, i32 e, i32 f) {
  return (p5(a, b, c, d, e) << 8) | (f as i64);
}
i64 p7(i32 a, i32 b, i32 c, i32 d, i32 e, i32 f, i32 g) {
  return (p6(a, b, c, d, e, f) << 8) | (g as i64);
}
i64 p8(i32 a, i32 b, i32 c, i32 d, i32 e, i32 f, i32 g, i32 h) {
  return (p7(a, b, c, d, e, f, g) << 8) | (h as i64);
}

/** The keyword kind for an identifier span, or `kIdent` if it is not a keyword. */
i32 keywordKind(u8[] src, i32 start, i32 len) {
  if (len < 2 || len > 8) { return kIdent(); }
  i64 v = packSpan(src, start, len);

  if (len == 2) {
    if (v == p2('i', 'f')) { return kIf(); }
    if (v == p2('d', 'o')) { return kDo(); }
    if (v == p2('i', 's')) { return kIs(); }
    if (v == p2('a', 's')) { return kAs(); }
    if (v == p2('f', 'n')) { return kFn(); }
    return kIdent();
  }
  if (len == 3) {
    if (v == p3('f', 'o', 'r')) { return kFor(); }
    if (v == p3('n', 'o', 't')) { return kNot(); }
    return kIdent();
  }
  if (len == 4) {
    if (v == p4('e', 'l', 's', 'e')) { return kElse(); }
    if (v == p4('c', 'a', 's', 'e')) { return kCase(); }
    if (v == p4('t', 'r', 'u', 'e')) { return kTrue(); }
    if (v == p4('n', 'u', 'l', 'l')) { return kNull(); }
    if (v == p4('v', 'o', 'i', 'd')) { return kVoid(); }
    if (v == p4('t', 'h', 'i', 's')) { return kThis(); }
    if (v == p4('t', 'r', 'a', 'p')) { return kTrap(); }
    if (v == p4('e', 'n', 'u', 'm')) { return kEnum(); }
    return kIdent();
  }
  if (len == 5) {
    if (v == p5('w', 'h', 'i', 'l', 'e')) { return kWhile(); }
    if (v == p5('b', 'r', 'e', 'a', 'k')) { return kBreak(); }
    if (v == p5('f', 'a', 'l', 's', 'e')) { return kFalse(); }
    if (v == p5('c', 'o', 'n', 's', 't')) { return kConst(); }
    if (v == p5('m', 'a', 't', 'c', 'h')) { return kMatch(); }
    return kIdent();
  }
  if (len == 6) {
    if (v == p6('i', 'm', 'p', 'o', 'r', 't')) { return kImport(); }
    if (v == p6('e', 'x', 'p', 'o', 'r', 't')) { return kExport(); }
    if (v == p6('s', 't', 'r', 'u', 'c', 't')) { return kStruct(); }
    if (v == p6('s', 'w', 'i', 't', 'c', 'h')) { return kSwitch(); }
    if (v == p6('r', 'e', 't', 'u', 'r', 'n')) { return kReturn(); }
    return kIdent();
  }
  if (len == 7) {
    if (v == p7('d', 'e', 'f', 'a', 'u', 'l', 't')) { return kDefault(); }
    return kIdent();
  }
  if (v == p8('c', 'o', 'n', 't', 'i', 'n', 'u', 'e')) { return kContinue(); }
  if (v == p8('o', 'v', 'e', 'r', 'r', 'i', 'd', 'e')) { return kOverride(); }
  return kIdent();
}

// ── Lexer ─────────────────────────────────────────────────────────────────────

/**
 * Lexer state.
 *
 * Held in a struct rather than as locals because the reference's closures over
 * `pos`/`line`/`col` have no equivalent: wac has no closures, so every helper takes
 * the state explicitly.
 */
struct Lexer {
  u8[] src;
  i32 pos;
  i32 line;
  i32 col;

  i32 peek(const this, i32 offset) {
    i32 at = this.pos + offset;
    if (at >= this.src.len()) { return -1; }   // -1 rather than 0: NUL is a real byte
    return this.src[at];
  }

  /**
   * Consume one byte, keeping `line` and `col` right.
   *
   * `col` counts UTF-16 code units so positions match the reference: continuation
   * bytes (0x80..0xBF) add nothing, a 4-byte lead adds two because it becomes a
   * surrogate pair, and anything else adds one.
   */
  i32 advance(this) {
    i32 c = this.src[this.pos];
    this.pos++;
    if (c == '\n') {
      this.line++;
      this.col = 1;
    } else if (c >= 0x80 && c < 0xC0) {
      // continuation byte: part of a character already counted
    } else if (c >= 0xF0) {
      this.col += 2;
    } else {
      this.col++;
    }
    return c;
  }

  bool atEnd(const this) { return this.pos >= this.src.len(); }
}

// ── Emitting ──────────────────────────────────────────────────────────────────
//
// The output arrays are pre-sized and written by index, so these take the Lexed
// value and mutate it rather than returning a new one.

void emit(Lexed out, i32 kind, i32 start, i32 len, i32 line, i32 col) {
  i32 at = out.tokenCount * tokenStride();
  out.tokens[at] = kind;
  out.tokens[at + 1] = start;
  out.tokens[at + 2] = len;
  out.tokens[at + 3] = line;
  out.tokens[at + 4] = col;
  out.tokenCount++;
}

void fail(Lexed out, i32 code, i32 line, i32 col) {
  i32 at = out.errorCount * errorStride();
  if (at + errorStride() > out.errors.len()) { return; }   // errors are capped
  out.errors[at] = code;
  out.errors[at + 1] = line;
  out.errors[at + 2] = col;
  out.errorCount++;
}

// ── Pieces ────────────────────────────────────────────────────────────────────

void skipSpaceAndComments(Lexer lx, Lexed out) {
  while (!lx.atEnd()) {
    i32 c = lx.peek(0);
    if (isSpace(c)) {
      lx.advance();
    } else if (c == '/' && lx.peek(1) == '/') {
      while (!lx.atEnd() && lx.peek(0) != '\n') { lx.advance(); }
    } else if (c == '/' && lx.peek(1) == '*') {
      i32 startLine = lx.line;
      i32 startCol = lx.col;
      lx.advance();
      lx.advance();
      bool closed = false;
      while (!lx.atEnd() && !closed) {
        if (lx.peek(0) == '*' && lx.peek(1) == '/') {
          lx.advance();
          lx.advance();
          closed = true;
        } else {
          lx.advance();
        }
      }
      if (!closed) { fail(out, errUnterminatedComment(), startLine, startCol); }
    } else {
      return;
    }
  }
}

/**
 * A string literal. The span kept is the whole literal including both quotes, so
 * a consumer can re-scan the escapes; the reference stores the decoded value
 * instead, and the differential test decodes the span to compare.
 */
void lexString(Lexer lx, Lexed out, i32 startLine, i32 startCol) {
  i32 start = lx.pos;
  lx.advance();                       // opening quote
  bool closed = false;
  while (!lx.atEnd() && !closed) {
    i32 c = lx.peek(0);
    if (c == '"') {
      lx.advance();
      closed = true;
    } else if (c == '\\') {
      lx.advance();
      if (lx.atEnd()) { break; }
      i32 esc = lx.advance();
      if (esc != 'n' && esc != 't' && esc != 'r' && esc != '\\'
          && esc != '"' && esc != '0' && esc != '\'') {
        fail(out, errUnknownEscape(), startLine, startCol);
      }
    } else {
      lx.advance();
    }
  }
  if (!closed) { fail(out, errUnterminatedString(), startLine, startCol); }
  emit(out, kString(), start, lx.pos - start, startLine, startCol);
}

/**
 * A character literal, emitted as an `int` whose span is the literal. The
 * reference emits the decimal codepoint as the token's text; the value is
 * recovered from the span by `tokenCodepoint`.
 */
void lexChar(Lexer lx, Lexed out, i32 startLine, i32 startCol) {
  i32 start = lx.pos;
  lx.advance();                       // opening quote

  if (lx.atEnd()) {
    fail(out, errUnterminatedChar(), startLine, startCol);
    emit(out, kInt(), start, lx.pos - start, startLine, startCol);
    return;
  }
  if (lx.peek(0) == '\'') {
    lx.advance();
    fail(out, errEmptyChar(), startLine, startCol);
    emit(out, kInt(), start, lx.pos - start, startLine, startCol);
    return;
  }

  if (lx.peek(0) == '\\') {
    lx.advance();
    if (lx.atEnd()) {
      fail(out, errUnterminatedChar(), startLine, startCol);
      emit(out, kInt(), start, lx.pos - start, startLine, startCol);
      return;
    }
    i32 esc = lx.advance();
    if (esc != 'n' && esc != 't' && esc != 'r' && esc != '\\'
        && esc != '"' && esc != '0' && esc != '\'') {
      fail(out, errUnknownEscape(), startLine, startCol);
    }
  } else {
    // One character, however many bytes it takes.
    lx.advance();
    while (!lx.atEnd() && lx.peek(0) >= 0x80 && lx.peek(0) < 0xC0) {
      lx.advance();
    }
  }

  if (lx.atEnd()) {
    fail(out, errUnterminatedChar(), startLine, startCol);
  } else if (lx.peek(0) == '\'') {
    lx.advance();
  } else {
    // More than one character before the closing quote.
    while (!lx.atEnd() && lx.peek(0) != '\'' && lx.peek(0) != '\n') { lx.advance(); }
    if (!lx.atEnd() && lx.peek(0) == '\'') { lx.advance(); }
    fail(out, errCharTooLong(), startLine, startCol);
  }
  emit(out, kInt(), start, lx.pos - start, startLine, startCol);
}

void lexNumber(Lexer lx, Lexed out, i32 startLine, i32 startCol) {
  i32 start = lx.pos;

  if (lx.peek(0) == '0' && (lx.peek(1) == 'x' || lx.peek(1) == 'X')) {
    lx.advance();
    lx.advance();
    while (!lx.atEnd() && (isHexDigit(lx.peek(0)) || lx.peek(0) == '_')) { lx.advance(); }
    emit(out, kInt(), start, lx.pos - start, startLine, startCol);
    return;
  }

  while (!lx.atEnd() && (isDigit(lx.peek(0)) || lx.peek(0) == '_')) { lx.advance(); }

  // A decimal point, an exponent, or both — either marks the literal a float. The reference stopped
  // requiring the point in wac issue 0018, and the differential test compares token for token, so
  // this has to move with it.
  if (lx.peek(0) == '.' && isDigit(lx.peek(1))) {
    lx.advance();
    while (!lx.atEnd() && (isDigit(lx.peek(0)) || lx.peek(0) == '_')) { lx.advance(); }
    takeExponent(lx);
    emit(out, kFloat(), start, lx.pos - start, startLine, startCol);
  } else if (takeExponent(lx)) {
    emit(out, kFloat(), start, lx.pos - start, startLine, startCol);
  } else {
    emit(out, kInt(), start, lx.pos - start, startLine, startCol);
  }
}

/**
 * Consume an exponent if one is really there, reporting whether it was.
 *
 * `1e` and `1electron` are an integer followed by an identifier, not malformed floats, so the digits
 * after `e` are what decides — checking for `e` alone would swallow the identifier.
 */
bool takeExponent(Lexer lx) {
  if (lx.peek(0) != 'e' && lx.peek(0) != 'E') { return false; }
  bool signed = lx.peek(1) == '+' || lx.peek(1) == '-';
  i32 digitAt = signed ? 2 : 1;
  if (!isDigit(lx.peek(digitAt))) { return false; }
  lx.advance();
  if (signed) { lx.advance(); }
  while (!lx.atEnd() && (isDigit(lx.peek(0)) || lx.peek(0) == '_')) { lx.advance(); }
  return true;
}

/**
 * `as`, `as!`, `as~` and `as@` — the one place an identifier can grow a suffix, so
 * it is handled where the identifier is recognised rather than with the operators.
 */
i32 identOrKeyword(Lexer lx, i32 start, i32 len) {
  i32 kind = keywordKind(lx.src, start, len);
  if (kind != kAs()) { return kind; }
  i32 c = lx.peek(0);
  if (c == '!') { lx.advance(); return kAsBang(); }
  if (c == '~') { lx.advance(); return kAsTilde(); }
  if (c == '@') { lx.advance(); return kAsAt(); }
  return kAs();
}

// ── Operators ─────────────────────────────────────────────────────────────────
//
// One function per lead byte, longest match first. Split out from the main loop
// because wac has no fallthrough and no multi-byte switch, so a single `switch`
// over the lead byte with nested prefix tests is the shape that stays readable.

/** The kind for an operator starting at the current position, consuming its bytes. */
i32 lexOperator(Lexer lx) {
  i32 c = lx.advance();

  if (c == '+') {
    if (lx.peek(0) == '+') { lx.advance(); return kInc(); }
    if (lx.peek(0) == '=') { lx.advance(); return kPlusEq(); }
    return kPlus();
  }
  if (c == '-') {
    if (lx.peek(0) == '-') { lx.advance(); return kDec(); }
    if (lx.peek(0) == '=') { lx.advance(); return kMinusEq(); }
    return kMinus();
  }
  if (c == '*') {
    if (lx.peek(0) == '=') { lx.advance(); return kStarEq(); }
    return kStar();
  }
  if (c == '/') {
    if (lx.peek(0) == '=') { lx.advance(); return kSlashEq(); }
    return kSlash();
  }
  if (c == '%') {
    if (lx.peek(0) == '=') { lx.advance(); return kPercentEq(); }
    return kPercent();
  }
  if (c == '=') {
    if (lx.peek(0) == '=') { lx.advance(); return kEq(); }
    return kAssign();
  }
  if (c == '!') {
    if (lx.peek(0) == '=') { lx.advance(); return kNe(); }
    return kBang();
  }
  if (c == '<') {
    if (lx.peek(0) == '<') {
      lx.advance();
      if (lx.peek(0) == '=') { lx.advance(); return kShlEq(); }
      return kShl();
    }
    if (lx.peek(0) == '=') { lx.advance(); return kLe(); }
    return kLt();
  }
  if (c == '>') {
    if (lx.peek(0) == '>') {
      lx.advance();
      if (lx.peek(0) == '>') {
        lx.advance();
        if (lx.peek(0) == '=') { lx.advance(); return kShrUEq(); }
        return kShrU();
      }
      if (lx.peek(0) == '=') { lx.advance(); return kShrEq(); }
      return kShr();
    }
    if (lx.peek(0) == '=') { lx.advance(); return kGe(); }
    return kGt();
  }
  if (c == '&') {
    if (lx.peek(0) == '&') { lx.advance(); return kAndAnd(); }
    if (lx.peek(0) == '=') { lx.advance(); return kAndEq(); }
    return kAnd();
  }
  if (c == '|') {
    if (lx.peek(0) == '|') { lx.advance(); return kOrOr(); }
    if (lx.peek(0) == '=') { lx.advance(); return kOrEq(); }
    return kOr();
  }
  if (c == '^') {
    if (lx.peek(0) == '=') { lx.advance(); return kCaretEq(); }
    return kCaret();
  }
  if (c == '~') { return kTilde(); }
  if (c == '(') { return kLparen(); }
  if (c == ')') { return kRparen(); }
  if (c == '{') { return kLbrace(); }
  if (c == '}') { return kRbrace(); }
  if (c == '[') { return kLbrack(); }
  if (c == ']') { return kRbrack(); }
  if (c == ';') { return kSemi(); }
  if (c == ':') { return kColon(); }
  if (c == ',') { return kComma(); }
  if (c == '.') { return kDot(); }
  if (c == '?') { return kQuestion(); }
  if (c == '@') { return kAt(); }

  return -1;   // not an operator: the caller reports it
}

// ── Entry point ───────────────────────────────────────────────────────────────

/**
 * Tokenize `src`.
 *
 * Output arrays are sized from the input: at most one token per byte, and errors
 * capped at a fraction of that since a pathological input would otherwise allocate
 * a triple per byte.
 */
export Lexed lex(u8[] src) {
  i32 n = src.len();
  i32 maxErrors = n / 4 + 8;
  Lexed out = Lexed(
    i32[(n + 1) * tokenStride()](), 0,
    i32[maxErrors * errorStride()](), 0
  );
  Lexer lx = Lexer(src, 0, 1, 1);

  while (true) {
    skipSpaceAndComments(lx, out);
    if (lx.atEnd()) { break; }

    i32 startLine = lx.line;
    i32 startCol = lx.col;
    i32 c = lx.peek(0);

    if (c == '"') {
      lexString(lx, out, startLine, startCol);
    } else if (c == '\'') {
      lexChar(lx, out, startLine, startCol);
    } else if (isDigit(c)) {
      lexNumber(lx, out, startLine, startCol);
    } else if (isIdentStart(c)) {
      i32 start = lx.pos;
      while (!lx.atEnd() && isIdentPart(lx.peek(0))) { lx.advance(); }
      i32 len = lx.pos - start;
      i32 kind = identOrKeyword(lx, start, len);
      // The cast suffixes lengthen the span, so it is measured after.
      emit(out, kind, start, lx.pos - start, startLine, startCol);
    } else {
      i32 start = lx.pos;
      i32 kind = lexOperator(lx);
      if (kind < 0) {
        fail(out, errUnexpectedChar(), startLine, startCol);
      } else {
        emit(out, kind, start, lx.pos - start, startLine, startCol);
      }
    }
  }

  emit(out, kEof(), n, 0, lx.line, lx.col);
  return out;
}

// ── Flat accessors for the host ───────────────────────────────────────────────
//
// bindgen cannot marshal a struct, so the host gets the arrays directly. Trimmed to
// the used length, since `lex` over-allocates from the source size.

export i32[] lexTokens(u8[] src) {
  Lexed r = lex(src);
  i32 n = r.tokenCount * tokenStride();
  i32[] out = i32[n]();
  for (i32 i = 0; i < n; i++) {
    out[i] = r.tokens[i];
  }
  return out;
}

export i32[] lexErrors(u8[] src) {
  Lexed r = lex(src);
  i32 n = r.errorCount * errorStride();
  i32[] out = i32[n]();
  for (i32 i = 0; i < n; i++) {
    out[i] = r.errors[i];
  }
  return out;
}
// ── What a literal denotes, in one place ─────────────────────────────────────
//
// The emitter needs a float literal's value to write a constant, and the checker needs it to decide
// whether the constant fits. When each read the text itself they disagreed — `f32 x = 1_0e38;` is
// out of range and the checker's reader stopped at the underscore, saw `1`, and let it through.
//
// The reference learned this first: `compiler/wacFloatLit.ts` exists because its emitter, checker
// and constant evaluator each called `parseFloat` and `parseFloat("1_000.5")` is `1` — its issue
// 0044. It can then delegate to a host that converts correctly; there is no such host here, so the
// conversion is written out below, and the reason for one copy is the same either way.

//
// `spec/spec/types.md` says a literal rounds to *nearest*, and nearest is not something floating
// point can be asked for while it is doing the asking: scaling a mantissa by ten repeatedly rounds
// at every step, and `1e300` came out a unit in the last place away. So the value is computed
// exactly — as one integer over another — and rounded once, at the end, where the answer is decided.
//
// The integers are base-2^16 limbs in an `i32[]`, which keeps every product inside an `i32` and
// makes the whole of this ordinary arithmetic. `10^350` is seventy-three limbs; a literal with eight
// hundred digits is under two hundred. Nothing here allocates per digit.

/** How many limbs a big integer is using — its length with the leading zeros dropped. */
i32 bigLen(i32[] a, i32 n) {
  i32 k = n;
  while (k > 0 && a[k - 1] == 0) { k = k - 1; }
  return k;
}

/** Its width in bits, which is what the alignment below is really asking about. */
i32 bigBits(i32[] a, i32 n) {
  i32 k = bigLen(a, n);
  if (k == 0) { return 0; }
  i32 top = a[k - 1];
  i32 bits = 0;
  while (top > 0) {
    bits = bits + 1;
    top = top >> 1;
  }
  return (k - 1) * 16 + bits;
}

/** `a = a * m + add`, with `m` and `add` small enough that a limb's product stays in an `i32`. */
i32 bigMulSmall(i32[] a, i32 n, i32 m, i32 add) {
  i32 carry = add;
  for (i32 i = 0; i < n; i++) {
    i32 cur = a[i] * m + carry;
    a[i] = cur & 65535;
    carry = cur >> 16;
  }
  i32 k = n;
  while (carry > 0) {
    if (k >= a.len()) { return k; }
    a[k] = carry & 65535;
    carry = carry >> 16;
    k = k + 1;
  }
  return k;
}

/** `a = a << k`, which is how the two sides are aligned before the division. */
i32 bigShl(i32[] a, i32 n, i32 k) {
  if (k == 0) { return n; }
  i32 limbs = k / 16;
  i32 bits = k % 16;
  i32 len = n + limbs + 1;
  if (len > a.len()) { len = a.len(); }
  for (i32 i = len - 1; i >= 0; i--) {
    i32 lo = i - limbs;
    i32 hi = lo - 1;
    i32 v = 0;
    if (lo >= 0 && lo < n) { v = (a[lo] << bits) & 65535; }
    if (bits > 0 && hi >= 0 && hi < n) { v = v | (a[hi] >> (16 - bits)); }
    a[i] = v;
  }
  return len;
}

/** -1, 0 or 1, comparing two big integers by magnitude. */
i32 bigCmp(i32[] a, i32 na, i32[] b, i32 nb) {
  i32 ka = bigLen(a, na);
  i32 kb = bigLen(b, nb);
  if (ka != kb) { return ka < kb ? 0 - 1 : 1; }
  for (i32 i = ka - 1; i >= 0; i--) {
    if (a[i] != b[i]) { return a[i] < b[i] ? 0 - 1 : 1; }
  }
  return 0;
}

/** `a = a - b`, where `a >= b`. */
void bigSub(i32[] a, i32 na, i32[] b, i32 nb) {
  i32 borrow = 0;
  for (i32 i = 0; i < na; i++) {
    i32 sub = borrow;
    if (i < nb) { sub = sub + b[i]; }
    i32 cur = a[i] - sub;
    if (cur < 0) {
      cur = cur + 65536;
      borrow = 1;
    } else {
      borrow = 0;
    }
    a[i] = cur;
  }
}

/**
 * The `f64` nearest to `digits × 10^exp10`, with ties to even — the bits, rather than the number.
 *
 * Assembling the pattern rather than computing the value is the point: every step above is integer
 * arithmetic, and the one rounding that happens is the one the specification names.
 */
f64 decimalToF64(u8[] digits, i32 count, i32 exp10) {
  i32[] num = i32[400]();
  i32[] den = i32[400]();
  num[0] = 0;
  den[0] = 1;
  i32 nn = 1;
  i32 dn = 1;
  bool any = false;
  for (i32 i = 0; i < count; i++) {
    nn = bigMulSmall(num, nn, 10, digits[i] - 48);
    if (digits[i] != 48) { any = true; }
  }
  if (!any) { return 0.0; }

  // `digits × 10^e` is one side or the other, exactly: a positive exponent multiplies the numerator
  // and a negative one the denominator, and neither is ever approximated.
  i32 e = exp10;
  while (e > 0) {
    nn = bigMulSmall(num, nn, 10, 0);
    e = e - 1;
  }
  while (e < 0) {
    dn = bigMulSmall(den, dn, 10, 0);
    e = e + 1;
  }

  // **Align so the quotient is in [1, 2), then take fifty-three of its bits.** The loop below
  // produces one bit per turn from the top, which is only the quotient's binary expansion while the
  // ratio starts in that interval — aligning it into [2^52, 2^53) instead makes the first turn
  // subtract the whole of the leading bit and every turn after it produce a zero. Every answer came
  // out an exact power of two, which is what that looks like from outside.
  i32 exp2 = 0;
  i32 diff = bigBits(num, nn) - bigBits(den, dn);
  if (diff > 0) {
    dn = bigShl(den, dn, diff);
    exp2 = exp2 + diff;
  }
  if (diff < 0) {
    nn = bigShl(num, nn, 0 - diff);
    exp2 = exp2 + diff;
  }
  if (bigCmp(num, nn, den, dn) < 0) {
    nn = bigShl(num, nn, 1);
    exp2 = exp2 - 1;
  }

  // **A subnormal is taken to a fixed place rather than to a fixed width.** Its last bit weighs
  // 2^-1074 whatever its leading bit is, so the count of bits shrinks as the exponent falls.
  i32 want = 53;
  if (exp2 < 0 - 1022) { want = exp2 + 1075; }
  if (want < 0) { want = 0; }

  i64 q = 0;
  for (i32 b = 0; b < want; b++) {
    q = q * 2;
    if (bigCmp(num, nn, den, dn) >= 0) {
      bigSub(num, nn, den, dn);
      q = q + 1;
    }
    nn = bigShl(num, nn, 1);
  }
  // One more bit decides the rounding and whatever is left over decides a tie — half to even.
  i32 roundBit = 0;
  if (bigCmp(num, nn, den, dn) >= 0) {
    bigSub(num, nn, den, dn);
    roundBit = 1;
  }
  bool sticky = bigLen(num, nn) > 0;
  if (roundBit == 1 && (sticky || (q & 1) == 1)) { q = q + 1; }

  if (want < 53) {
    // The subnormal pattern *is* the integer: a mantissa of 2^52 with a zero exponent field is
    // read as the smallest normal, which is exactly what rounding up to it should produce.
    return f64.fromBits(q as@ u64);
  }
  // A carry out of the mantissa is a larger exponent, not a wider mantissa.
  // Two to the fifty-third is one past the top of the mantissa: rounding that far is a carry.
  if (q >= 9007199254740992) {
    q = q / 2;
    exp2 = exp2 + 1;
  }
  i64 biased = (exp2 + 1023) as i64;
  if (biased >= 2047) { return f64.fromBits(9218868437227405312 as@ u64); }
  if (biased <= 0) { return 0.0; }
  // The implicit bit is two to the **fifty-second**, not the fifty-third. Taking the larger one
  // away made the mantissa negative, which borrows from the exponent — so every answer came out
  // exactly half of itself, which is a wrong number that looks like a rounding bug.
  return f64.fromBits((biased * 4503599627370496 + (q - 4503599627370496)) as@ u64);
}

/**
 * A float literal's value, exactly.
 *
 * The text is split into its digits and a decimal exponent, and the arithmetic is left to
 * `decimalToF64`, which does it in integers. Underscores are separators wherever they appear —
 * `1_000.5` read as `1` before anyone looked, which is the third literal spelling to be silently
 * wrong here after `0xff` and `' '`.
 */
export f64 floatLit(string s) {
  u8[] a = s.toBytes();
  u8[] digits = u8[a.len() + 1]();
  i32 count = 0;
  i32 frac = 0;
  i32 i = 0;
  while (i < a.len()) {
    i32 c = a[i];
    if (c == 95) {
      i = i + 1;
      continue;
    }
    if (c < 48 || c > 57) { break; }
    digits[count] = c;
    count = count + 1;
    i = i + 1;
  }
  if (i < a.len() && a[i] == 46) {
    i = i + 1;
    while (i < a.len()) {
      i32 c2 = a[i];
      if (c2 == 95) {
        i = i + 1;
        continue;
      }
      if (c2 < 48 || c2 > 57) { break; }
      digits[count] = c2;
      count = count + 1;
      frac = frac + 1;
      i = i + 1;
    }
  }
  i32 exp = 0;
  bool neg = false;
  if (i < a.len() && (a[i] == 101 || a[i] == 69)) {
    i = i + 1;
    if (i < a.len() && (a[i] == 43 || a[i] == 45)) {
      neg = a[i] == 45;
      i = i + 1;
    }
    while (i < a.len()) {
      i32 c3 = a[i];
      if (c3 == 95) {
        i = i + 1;
        continue;
      }
      if (c3 < 48 || c3 > 57) { break; }
      exp = exp * 10 + (c3 - 48);
      i = i + 1;
    }
  }
  i32 e10 = (neg ? 0 - exp : exp) - frac;
  // Past these the answer is zero or infinity whatever the digits are, and the exact path would be
  // asked for a power of ten with three thousand digits in it.
  if (e10 > 400) { e10 = 400; }
  if (e10 < 0 - 400) { e10 = 0 - 400; }
  return decimalToF64(digits, count, e10);
}

/**
 * A decimal integer literal's value, at `i64`.
 *
 * Accumulated wide even when the target is narrow, because the literal's *text* says nothing about
 * which it is: `4294967296` in an `i64` slot is a real value and parsing into an `i32` made it zero.
 * The narrowing happens at the point the constant is written, where the target is known.
 */
/**
 * The scalar a character literal denotes: an escape, or the UTF-8 sequence spelled between quotes.
 *
 * The escapes are the ones the language writes — and `\'`, which no string literal needs and every
 * character literal of a quote does.
 */
export i64 charValue(u8[] a) {
  if (a[1] == 92) {
    i32 e = a[2];
    if (e == 110) { return 10; }    // \n
    if (e == 116) { return 9; }     // \t
    if (e == 114) { return 13; }    // \r
    if (e == 48) { return 0; }      // \0
    if (e == 92) { return 92; }
    if (e == 39) { return 39; }
    if (e == 34) { return 34; }
    return e as i64;
  }
  // Otherwise a UTF-8 sequence, decoded from its lead byte exactly as `str_idx` decodes one.
  i32 b0 = a[1];
  if (b0 < 128) { return b0 as i64; }
  if (b0 < 224 && a.len() >= 4) {
    return (((b0 & 31) * 64) + (a[2] & 63)) as i64;
  }
  if (b0 < 240 && a.len() >= 5) {
    return (((b0 & 15) * 4096) + ((a[2] & 63) * 64) + (a[3] & 63)) as i64;
  }
  if (a.len() >= 6) {
    return (((b0 & 7) * 262144) + ((a[2] & 63) * 4096) + ((a[3] & 63) * 64) + (a[4] & 63)) as i64;
  }
  return 0;
}

/**
 * The value of an integer literal's text — decimal, hex, separators, and a character literal.
 *
 * Moved here from the emitter so the *checker* can ask too: whether `4294967296` fits an `i32` is a
 * question about the literal, and a second parser to answer it is a second parser to disagree with.
 */
export i64 parseInt(string s) {
  u8[] a = s.toBytes();
  i64 v = 0;
  // **A character literal is an integer literal**, and it arrives here as its own text — `'a'`,
  // quotes and all. Reading digits out of that gives 0, which is not a decline but a *wrong answer*:
  // `isSpace(c)` became `c == 0`, and the lexer this compiler is part of skipped nothing and
  // tokenised nothing. Every literal in the sweep was a number, again, which is the third time that
  // sentence has been written here.
  if (a.len() >= 3 && a[0] == 39) { return charValue(a); }
  // **Hex and separators.** Reading decimal digits and stopping at anything else made `0xff` into 0
  // and `1_000` into 1 — a *wrong answer* rather than a decline, which is the failure mode this rung
  // exists to catch and which no differential case had, because every literal in them was plain.
  if (a.len() > 2 && a[0] == 48 && (a[1] == 120 || a[1] == 88)) {
    for (i32 i = 2; i < a.len(); i++) {
      i32 c = a[i];
      if (c == 95) { continue; }
      i32 d = -1;
      if (c >= 48 && c <= 57) { d = c - 48; }
      if (c >= 97 && c <= 102) { d = c - 87; }
      if (c >= 65 && c <= 70) { d = c - 55; }
      if (d < 0) { break; }
      v = v * 16 + d as i64;
    }
    return v;
  }
  for (i32 i = 0; i < a.len(); i++) {
    if (a[i] == 95) { continue; }
    if (a[i] < 48 || a[i] > 57) { break; }
    v = v * 10 + (a[i] - 48) as i64;
  }
  return v;
}
// The wac parser, in wac. Port of compiler/wacParse.ts.
//
// Recursive descent over the token array the lexer produces, building the sum-type
// AST in ast.wac. Structured as a `P` struct threaded through every function, since
// wac has no closures to capture the position the way the reference does.
//
// The reference takes positions at very specific points — a binary node's position is
// its *operator*, a ternary's is the `?`, not the start of the condition — and this
// mirrors that exactly, because the differential test compares them. Where a `pos()`
// call looks oddly placed here, it is placed where the reference places it.
//
// Scope so far: types, the whole expression precedence ladder, and lvalues.
// Statements and declarations are next; `parseExprEntry` is the tested entry point
// until then.

