// ── Primitive type names ──────────────────────────────────────────────────────

/** Is the identifier at `offset` one of the primitive type names? */
bool identIsPrim(P p, i32 offset) {
  return spanIsPrimName(p.src, p.startAt(offset), p.lenAt(offset));
}

/**
 * The primitive type names, matched by packing the span into an i64.
 *
 * The reference uses a `Set<string>`. There is no string-keyed set here, and every
 * name is 8 bytes or fewer, so the same integer-packing trick the lexer uses for
 * keywords applies — allocation free, and exact.
 */
bool spanIsPrimName(u8[] s, i32 start, i32 len) {
  if (len < 2 || len > 6) { return false; }
  i64 v = 0 as i64;
  for (i32 i = 0; i < len; i++) {
    v = (v << 8) | (s[start + i] as i64);
  }
  if (len == 2) {
    return v == q2('i', '8') || v == q2('u', '8');
  }
  if (len == 3) {
    return v == q3('i', '3', '2') || v == q3('i', '6', '4')
        || v == q3('u', '3', '2') || v == q3('u', '6', '4')
        || v == q3('f', '3', '2') || v == q3('f', '6', '4')
        || v == q3('i', '1', '6') || v == q3('u', '1', '6');
  }
  if (len == 4) {
    return v == q4('b', 'o', 'o', 'l') || v == q4('v', 'o', 'i', 'd');
  }
  if (len == 6) {
    return v == q6('s', 't', 'r', 'i', 'n', 'g') || v == q6('a', 'n', 'y', 'r', 'e', 'f')
        || v == q6('i', '3', '1', 'r', 'e', 'f');
  }
  return false;
}

i64 q2(i32 a, i32 b) { return ((a as i64) << 8) | (b as i64); }
i64 q3(i32 a, i32 b, i32 c) { return (q2(a, b) << 8) | (c as i64); }
i64 q4(i32 a, i32 b, i32 c, i32 d) { return (q3(a, b, c) << 8) | (d as i64); }
i64 q6(i32 a, i32 b, i32 c, i32 d, i32 e, i32 f) {
  return (((q4(a, b, c, d) << 8) | (e as i64)) << 8) | (f as i64);
}

// ── Types ─────────────────────────────────────────────────────────────────────

/**
 * Split a munched `>>` or `>>>` so a nested type-argument list can close.
 *
 * `Vec<Vec<i32>>` ends in what the lexer read as one shift operator, and the lexer is a pure token
 * stream that knows nothing about nesting. So the parser consumes one `>` worth and rewrites the rest
 * in place — the same trick the reference calls `replaceCurrent`, and the reason `P.toks` is mutable.
 *
 * The position moves with it: the remaining `>` begins one byte later and one column further on, which
 * is what the reference records and therefore what the differential compares.
 */
void splitGt(P p) {
  i32 base = p.abs(0) * tokenStride();
  p.toks[base] = p.kindAt(0) == kShrU() ? kShr() : kGt();
  p.toks[base + 1] = p.toks[base + 1] + 1;
  p.toks[base + 2] = p.toks[base + 2] - 1;
  p.toks[base + 4] = p.toks[base + 4] + 1;
}

/** Whether the current token closes a type-argument list, in any of its munched forms. */
bool atTypeArgEnd(P p) {
  return p.at1(kGt()) || p.at1(kShr()) || p.at1(kShrU());
}

/**
 * `<i32>` or `<string, Vec<i32>>` after a name — empty when there is no `<` at all.
 *
 * Type arguments are what made `packages/std` unreadable here: twenty-five files in the corpus use
 * them, and a parser that stops at `Vec<` cannot compare against anything. wac-mono 0003.
 */
Ty[] parseTypeArgs(P p) {
  TyList args = TyList.create();
  if (!p.at1(kLt())) { return args.take(); }
  p.advance();
  if (!atTypeArgEnd(p)) {
    args.push(parseType(p));
    while (p.eat(kComma())) {
      if (atTypeArgEnd(p)) { break; }              // trailing comma, as in every other list
      args.push(parseType(p));
    }
  }
  // `>>` closes two lists and `>>>` three: take one `>` worth and leave the rest for the caller.
  if (p.at1(kShr()) || p.at1(kShrU())) { splitGt(p); } else { p.expect(kGt()); }
  return args.take();
}

/** `<T>` or `<T, U>` after a declaration's name: the name tokens, empty when there are none. */
i32[] parseTypeParams(P p) {
  I32List params = I32List.create();
  if (!p.at1(kLt())) { return params.take(); }
  p.advance();
  if (!p.at1(kGt())) {
    while (true) {
      if (p.at1(kGt())) { break; }                 // trailing comma
      if (p.at1(kIdent())) { params.push(p.advance()); } else { p.fail(perrExpected()); }
      if (!p.eat(kComma())) { break; }
    }
  }
  p.expect(kGt());
  return params.take();
}

/**
 * Skip a balanced `<…>` starting at `from`, or return -1 when there is not one.
 *
 * Shared by the two lookaheads that need it — a declaration against an expression statement, and a
 * construction against a comparison — because they ask the same question about the same shape and the
 * reference had a bug in each of them separately. Parentheses and brackets are tracked, since
 * `Box<fn[i32(i32)]>` contains both and a scan that stopped at the funcref's own `)` read the whole
 * declaration as an expression. A `;` or `{` ends the scan: neither can appear inside a type.
 */
i32 afterTypeArgs(P p, i32 from) {
  if (p.kindAt(from) != kLt()) { return -1; }
  i32 depth = 0;
  i32 group = 0;
  i32 k = from;
  while (p.kindAt(k) != kEof()) {
    i32 kind = p.kindAt(k);
    if (kind == kLparen() || kind == kLbrack()) { group++; }
    else if (kind == kRparen() || kind == kRbrack()) {
      if (group == 0) { break; }                   // a closer nothing opened: not a type list
      group--;
    } else if (kind == kLt()) { depth++; }
    else if (kind == kGt()) {
      depth--;
      if (depth == 0) { k++; break; }
    } else if (kind == kShr()) {
      depth -= 2;
      if (depth <= 0) { k++; break; }
    } else if (kind == kShrU()) {
      depth -= 3;
      if (depth <= 0) { k++; break; }
    } else if (kind == kSemi() || kind == kLbrace()) { break; }
    k++;
  }
  if (depth <= 0 && k > from) { return k; }
  return -1;
}

export Ty parseType(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  Ty node = tyPrim(-1, line, col);

  if (p.at1(kFn())) {
    p.advance();
    p.expect(kLbrack());
    Ty ret = parseType(p);
    p.expect(kLparen());
    TyList params = TyList.create();
    if (!p.at1(kRparen())) {
      params.push(parseType(p));
      while (p.eat(kComma())) {
        if (p.at1(kRparen())) { break; }
        params.push(parseType(p));
      }
    }
    p.expect(kRparen());
    p.expect(kRbrack());
    node = tyFuncref(ret, params.take(), line, col);
  } else if (p.at1(kIdent()) || p.at1(kVoid())) {
    bool prim = identIsPrim(p, 0);
    i32 t = p.advance();
    // A primitive takes no arguments and must not eat a `<`: `i32 < n` is a comparison.
    Ty[] args = prim ? Ty[]() : parseTypeArgs(p);
    node = prim ? tyPrim(t, line, col) : tyNamed(t, args, line, col);
  } else {
    // The reference reports the error and *substitutes* `i32` without consuming
    // anything, then goes on to parse suffixes. Advancing here instead would desync
    // the two parsers for the rest of the file, so this does neither. A prim with no
    // name token is that substitution; the printer renders it as `i32`.
    p.fail(perrBadType());
  }

  // Suffixes interleave and bind left to right: `Node?[]` is an array of nullable,
  // `i32[]?` a nullable array. Each suffix node takes the position of its own token,
  // not of the base type — which is what the reference does, and the difference shows
  // up on every array type in the corpus.
  while (true) {
    if (p.at1(kLbrack()) && p.at2(kRbrack(), 1)) {
      i32 aLine = p.lineAt(0);
      i32 aCol = p.colAt(0);
      p.advance();
      p.advance();
      node = tyArr(node, aLine, aCol);
    } else if (p.at1(kQuestion())) {
      i32 nLine = p.lineAt(0);
      i32 nCol = p.colAt(0);
      p.advance();
      node = tyNullable(node, nLine, nCol);
    } else {
      return node;
    }
  }
  return node;
}

/**
 * Could a type start here?
 *
 * Only asked after `is`, where the right side may be a type (`x is Circle`) or a
 * value (`x is y`, testing reference identity). The two are not distinguishable from
 * the grammar, so the reference decides by **naming convention**: an identifier
 * beginning with a lowercase letter is a value, anything else may be a type. Then a
 * follow-set breaks the remaining ties.
 *
 * This is ported rule for rule rather than reasoned out, because a plausible-looking
 * approximation of it got two files in the corpus wrong — `(a is b) && (a is not c)`
 * in the tour, and `byStr! is byBytes!` in the json tests — in both cases by reading
 * a lowercase variable as a type name.
 */
bool looksLikeTypeHere(P p) {
  if (p.at1(kFn())) { return true; }
  if ((p.at1(kIdent()) && identIsPrim(p, 0)) || p.at1(kVoid())) { return true; }
  if (!p.at1(kIdent())) { return false; }
  i32 next = p.kindAt(1);
  // A `[` or `?` after the name makes it an array or nullable type either way.
  if (next == kLbrack() || next == kQuestion()) { return true; }
  // Lowercase initial: a variable, by the struct-naming convention.
  if (startsLower(p.src, p.startAt(0), p.lenAt(0))) { return false; }
  bool exprFollow = next == kLparen() || next == kIdent()
      || next == kPlus() || next == kMinus() || next == kStar() || next == kSlash()
      || next == kPercent() || next == kEq() || next == kNe()
      || next == kLt() || next == kGt() || next == kLe() || next == kGe()
      || next == kAndAnd() || next == kOrOr() || next == kDot()
      || next == kLbrack() || next == kBang() || next == kTilde();
  bool typeFollow = next == kRparen() || next == kSemi() || next == kRbrace()
      || next == kComma() || next == kColon() || next == kEof();
  return !exprFollow || typeFollow;
}

/**
 * Does this identifier begin with a lowercase letter?
 *
 * The reference asks whether the first character differs from its uppercase form,
 * which for an ASCII identifier is exactly this. wac identifiers are ASCII, so the
 * two agree; a non-letter first character (`_`) counts as not-lowercase in both.
 */
bool startsLower(u8[] s, i32 start, i32 len) {
  if (len == 0) { return false; }
  i32 c = s[start];
  return c >= 'a' && c <= 'z';
}

// ── Expressions ───────────────────────────────────────────────────────────────

export Expr parseExpr(P p) { return parseTernary(p); }

Expr parseTernary(P p) {
  Expr e = parseIsExpr(p);
  if (p.at1(kQuestion())) {
    i32 line = p.lineAt(0);
    i32 col = p.colAt(0);
    p.advance();
    Expr then = parseExpr(p);
    p.expect(kColon());
    Expr els = parseExpr(p);
    return Expr(ExprKind.Ternary(e, then, els), line, col);
  }
  return e;
}

Expr parseIsExpr(P p) {
  Expr e = parseOr(p);
  if (!p.at1(kIs())) { return e; }
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  p.advance();
  bool negated = p.eat(kNot());

  // `is null` — neither a type nor a value on the right.
  if (p.at1(kNull())) {
    p.advance();
    return Expr(ExprKind.Is(e, null, null, negated), line, col);
  }

  if (looksLikeTypeHere(p)) {
    Ty t = parseType(p);
    // `s is Circle ? 1 : 0` — parseType ate the `?` as a nullable suffix when it is
    // really the ternary operator. Detected the same way the reference detects it:
    // the last token consumed was `?` and what follows can start an expression.
    if (p.kindAt(-1) == kQuestion() && startsExpr(p)) {
      Ty inner = tyOfNullableInner(t);
      p.at = p.at - 1;                       // put the `?` back for parseTernary
      return Expr(ExprKind.Is(e, inner, null, negated), line, col);
    }
    return Expr(ExprKind.Is(e, t, null, negated), line, col);
  }

  // Not a type: `is` against a value, which tests reference identity.
  Expr other = parseOr(p);
  return Expr(ExprKind.Is(e, null, other, negated), line, col);
}

/** The inner type of a nullable, or the type itself when it is not one. */
Ty tyOfNullableInner(Ty t) {
  match (t.kind) {
    case Nullable(inner): return inner;
    else: return t;
  }
}

/** Can the current token begin an expression? Mirrors the reference's list exactly. */
bool startsExpr(P p) {
  i32 k = p.kindAt(0);
  return k == kInt() || k == kFloat() || k == kString()
      || k == kLparen() || k == kBang() || k == kTilde() || k == kMinus()
      || k == kIdent() || k == kTrue() || k == kFalse() || k == kThis();
}

Expr parseOr(P p) {
  Expr e = parseAnd(p);
  while (p.at1(kOrOr())) {
    i32 line = p.lineAt(0); i32 col = p.colAt(0);
    i32 op = p.advance();
    e = Expr(ExprKind.Binary(op, e, parseAnd(p)), line, col);
  }
  return e;
}

Expr parseAnd(P p) {
  Expr e = parseBitor(p);
  while (p.at1(kAndAnd())) {
    i32 line = p.lineAt(0); i32 col = p.colAt(0);
    i32 op = p.advance();
    e = Expr(ExprKind.Binary(op, e, parseBitor(p)), line, col);
  }
  return e;
}

Expr parseBitor(P p) {
  Expr e = parseXor(p);
  while (p.at1(kOr())) {
    i32 line = p.lineAt(0); i32 col = p.colAt(0);
    i32 op = p.advance();
    e = Expr(ExprKind.Binary(op, e, parseXor(p)), line, col);
  }
  return e;
}

Expr parseXor(P p) {
  Expr e = parseBitand(p);
  while (p.at1(kCaret())) {
    i32 line = p.lineAt(0); i32 col = p.colAt(0);
    i32 op = p.advance();
    e = Expr(ExprKind.Binary(op, e, parseBitand(p)), line, col);
  }
  return e;
}

Expr parseBitand(P p) {
  Expr e = parseEqExpr(p);
  while (p.at1(kAnd())) {
    i32 line = p.lineAt(0); i32 col = p.colAt(0);
    i32 op = p.advance();
    e = Expr(ExprKind.Binary(op, e, parseEqExpr(p)), line, col);
  }
  return e;
}

Expr parseEqExpr(P p) {
  Expr e = parseRel(p);
  while (p.at1(kEq()) || p.at1(kNe())) {
    i32 line = p.lineAt(0); i32 col = p.colAt(0);
    i32 op = p.advance();
    e = Expr(ExprKind.Binary(op, e, parseRel(p)), line, col);
  }
  return e;
}

Expr parseRel(P p) {
  Expr e = parseShift(p);
  while (p.at1(kLt()) || p.at1(kLe()) || p.at1(kGt()) || p.at1(kGe())) {
    i32 line = p.lineAt(0); i32 col = p.colAt(0);
    i32 op = p.advance();
    e = Expr(ExprKind.Binary(op, e, parseShift(p)), line, col);
  }
  return e;
}

Expr parseShift(P p) {
  Expr e = parseAdd(p);
  while (p.at1(kShl()) || p.at1(kShr()) || p.at1(kShrU())) {
    i32 line = p.lineAt(0); i32 col = p.colAt(0);
    i32 op = p.advance();
    e = Expr(ExprKind.Binary(op, e, parseAdd(p)), line, col);
  }
  return e;
}

Expr parseAdd(P p) {
  Expr e = parseMul(p);
  while (p.at1(kPlus()) || p.at1(kMinus())) {
    i32 line = p.lineAt(0); i32 col = p.colAt(0);
    i32 op = p.advance();
    e = Expr(ExprKind.Binary(op, e, parseMul(p)), line, col);
  }
  return e;
}

Expr parseMul(P p) {
  Expr e = parseCast(p);
  while (p.at1(kStar()) || p.at1(kSlash()) || p.at1(kPercent())) {
    i32 line = p.lineAt(0); i32 col = p.colAt(0);
    i32 op = p.advance();
    e = Expr(ExprKind.Binary(op, e, parseCast(p)), line, col);
  }
  return e;
}

Expr parseCast(P p) {
  Expr e = parseUnary(p);
  while (p.at1(kAs()) || p.at1(kAsBang()) || p.at1(kAsTilde()) || p.at1(kAsAt())) {
    i32 line = p.lineAt(0); i32 col = p.colAt(0);
    i32 op = p.advance();
    Ty t = parseType(p);
    e = Expr(ExprKind.Cast(op, e, t), line, col);
  }
  return e;
}

Expr parseUnary(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  if (p.at1(kMinus()) || p.at1(kBang()) || p.at1(kTilde())) {
    i32 op = p.advance();
    return Expr(ExprKind.Unary(op, parseUnary(p)), line, col);
  }
  if (p.at1(kInc()) || p.at1(kDec())) {
    i32 op = p.advance();
    Expr operand = parseUnary(p);
    Lvalue? lv = exprToLvalue(operand);
    if (lv is null) {
      p.fail(perrBadLvalue());
      return operand;
    }
    return Expr(ExprKind.Incr(lv!, op, true), line, col);
  }
  return parsePostfix(p);
}

Expr parsePostfix(P p) {
  Expr e = parsePrimary(p);
  while (true) {
    i32 line = p.lineAt(0);
    i32 col = p.colAt(0);
    if (p.at1(kDot())) {
      p.advance();
      i32 nameTok = -1;
      nameTok = declName(p, perrFieldName());
      if (p.at1(kLparen())) {
        p.advance();
        Expr[] args = parseArgList(p);
        p.expect(kRparen());
        Expr callee = Expr(ExprKind.Member(e, nameTok), line, col);
        e = Expr(ExprKind.Call(callee, args), line, col);
      } else {
        e = Expr(ExprKind.Member(e, nameTok), line, col);
      }
    } else if (p.at1(kLbrack())) {
      p.advance();
      Expr idx = parseExpr(p);
      p.expect(kRbrack());
      e = Expr(ExprKind.Index(e, idx), line, col);
    } else if (p.at1(kBang())) {
      // `x!` unwrap — but `x != y` is not one, and the lexer emits `!=` as one token
      // so there is nothing to disambiguate here beyond checking the kind.
      p.advance();
      e = Expr(ExprKind.Unwrap(e), line, col);
    } else if (p.at1(kLparen())) {
      p.advance();
      Expr[] args = parseArgList(p);
      p.expect(kRparen());
      e = Expr(ExprKind.Call(e, args), line, col);
    } else if (p.at1(kInc()) || p.at1(kDec())) {
      i32 op = p.advance();
      Lvalue? lv = exprToLvalue(e);
      if (lv is null) {
        p.fail(perrBadLvalue());
        return e;
      }
      e = Expr(ExprKind.Incr(lv!, op, false), line, col);
    } else {
      return e;
    }
  }
  return e;
}

/**
 * The tail of an array construction, from the `[` that opens it.
 *
 * `T[](a, b)` is the fixed literal and `T[N]()` / `T[N](fill: v)` the sized form. Shared because a
 * funcref element type arrives by another road — `parseType` eats the brackets of `fn[R(P)]`
 * itself — and only the fixed literal was reachable that way [issue 0079].
 */
Expr parseArrayCtorTail(P p, Ty elem, i32 line, i32 col) {
  p.advance();                       // the construction `[`
  if (!p.at1(kRbrack())) {
    Expr size = parseExpr(p);        // `T[N]()` or `T[N](fill: v)`
    p.expect(kRbrack());
    p.expect(kLparen());
    Expr? fill = null;
    if (!p.at1(kRparen())) {
      if (p.at1(kIdent()) && spanIsFill(p.src, p.startAt(0), p.lenAt(0))
          && p.kindAt(1) == kColon()) {
        p.advance();
        p.advance();
        fill = parseExpr(p);
      } else {
        p.fail(perrExpected());
      }
    }
    p.expect(kRparen());
    Expr[] empty = Expr[]();
    return Expr(ExprKind.ArrNew(elem, size, fill, empty), line, col);
  }
  p.advance();                       // `]`
  p.expect(kLparen());
  Expr[] args = parseArgList(p);
  p.expect(kRparen());
  return Expr(ExprKind.ArrNew(elem, null, null, args), line, col);
}

Expr[] parseArgList(P p) {
  ExprList args = ExprList.create();
  if (p.at1(kRparen())) { return args.take(); }
  while (true) {
    if (p.at1(kRparen())) { return args.take(); }   // trailing comma
    args.push(parseExpr(p));
    if (!p.eat(kComma())) { return args.take(); }
  }
  return args.take();
}

Expr parsePrimary(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);

  if (p.at1(kNull()))  { p.advance(); return Expr(ExprKind.NullLit, line, col); }
  if (p.at1(kTrue()))  { p.advance(); return Expr(ExprKind.BoolLit(true), line, col); }
  if (p.at1(kFalse())) { p.advance(); return Expr(ExprKind.BoolLit(false), line, col); }
  if (p.at1(kInt()))   { return Expr(ExprKind.IntLit(p.advance()), line, col); }
  if (p.at1(kFloat())) { return Expr(ExprKind.FloatLit(p.advance()), line, col); }
  if (p.at1(kString())) { return Expr(ExprKind.StrLit(p.advance()), line, col); }
  // `match (subject) { case P: value, … }` as an expression. The arm syntax is the statement's, so
  // there is one of it in the language; which form is being parsed is decided by *position* — this is
  // expression position — and nothing is ambiguous.
  if (p.at1(kMatch())) { return parseMatchExpr(p); }

  // `this` is an identifier expression, as in the reference.
  if (p.at1(kThis()))  { return Expr(ExprKind.Ident(p.advance()), line, col); }

  // Grouping. The reference returns the inner expression unwrapped, so the
  // parentheses leave no trace in the tree.
  if (p.at1(kLparen())) {
    p.advance();
    Expr e = parseExpr(p);
    p.expect(kRparen());
    return e;
  }

  // `fn[R(P)][](args)` — an array of funcrefs.
  if (p.at1(kFn())) {
    Ty t = parseType(p);
    match (t.kind) {
      case Arr(elem): {
        if (p.at1(kLparen())) {
          p.advance();
          Expr[] args = parseArgList(p);
          p.expect(kRparen());
          return Expr(ExprKind.ArrNew(elem, null, null, args), line, col);
        }
        // `fn[R(P)][][2](fill: v)` — the element is the whole array type, not its element.
        if (p.at1(kLbrack())) { return parseArrayCtorTail(p, t, line, col); }
        p.fail(perrFnArray());
        return Expr(ExprKind.NullLit, line, col);
      }
      else: {
        // `parseType` stops at `[2` and hands back the funcref, so the sized spelling lands here
        // rather than in the arm above [issue 0079].
        if (p.at1(kLbrack())) { return parseArrayCtorTail(p, t, line, col); }
        p.fail(perrFnArray());
        return Expr(ExprKind.NullLit, line, col);
      }
    }
  }

  if (looksLikeConstructionOrCall(p)) {
    return parseConstructionOrCall(p, line, col);
  }

  if (p.at1(kIdent())) {
    return Expr(ExprKind.Ident(p.advance()), line, col);
  }

  p.fail(perrBadPrimary());
  if (!p.at1(kEof()) && !p.at1(kSemi()) && !p.at1(kRbrace())) { p.advance(); }
  return Expr(ExprKind.NullLit, line, col);
}

/**
 * Does a construction or static call start here?
 *
 * The subtle case is `T[...]`: `Node[5]()` constructs, `arr[i]` indexes, and
 * `arr[i](5)` indexes then calls. Distinguishing them needs a scan to the matching
 * bracket and a look at what follows, which is what the reference does.
 */
bool looksLikeConstructionOrCall(P p) {
  if (!p.at1(kIdent())) { return false; }
  i32 next = p.kindAt(1);

  if (identIsPrim(p, 0)) {
    // A primitive name is only ever construction with `(` or `[` — and with `?[`, which is an array of
    // *nullable* primitives: `i32?[3]()` is the same shape as `Node?[3]()`, and only the named case was
    // accepted here. The reference grew that third arm and this port did not, so the two disagreed about
    // a program neither the corpus nor the synthetic cases contained. wac-mono 0005 found it by asking
    // why the `anyref` guard below could not be killed.
    return next == kLparen() || next == kLbrack()
        || (next == kQuestion() && p.kindAt(2) == kLbrack());
  }

  if (next == kDot() || next == kLparen() || next == kLbrace()) { return true; }

  // `Vec<i32>(…)`, `Vec<i32>[0]()`, `Map<K, V>.create()`, `MapEntry<K, V>?[8]()` — skip the argument
  // list and ask what follows it. `?` belongs in that set as much as `[`: an array of nullable
  // instantiations is how a hash table spells an empty slot.
  if (next == kLt()) {
    i32 after = afterTypeArgs(p, 1);
    if (after < 0) { return false; }
    i32 following = p.kindAt(after);
    return following == kLbrack() || following == kLparen() || following == kLbrace()
        || following == kQuestion();
  }

  if (next == kLbrack() || next == kQuestion()) {
    i32 j = 1;                        // relative offset of the `[` or `?`
    // Skip element-type suffixes: `[]` pairs and `?`.
    bool lastWasBracketPair = false;
    while (true) {
      if (p.kindAt(j) == kLbrack() && p.kindAt(j + 1) == kRbrack()) {
        j += 2;
        lastWasBracketPair = true;
      } else if (p.kindAt(j) == kQuestion()) {
        j++;
        lastWasBracketPair = false;
      } else { break; }
    }
    // A fixed literal with a named element type: `S[](S(1), S(2))`. The final `[]` pair
    // is the construction bracket, so the scan lands on `(` with no size bracket to
    // find. An empty `[]` cannot be an index, so there is no ambiguity.
    if (lastWasBracketPair && p.kindAt(j) == kLparen()) { return true; }
    if (p.kindAt(j) != kLbrack()) { return false; }
    j++;
    i32 depth = 1;
    while (depth > 0 && p.kindAt(j) != kEof()) {
      if (p.kindAt(j) == kLbrack()) { depth++; }
      else if (p.kindAt(j) == kRbrack()) { depth--; }
      j++;
    }
    // `T[N](fill: v)` gives every element a value. A call cannot take a named argument,
    // so this is unambiguous where a bare `T[N](v)` would collide with `arr[i](5)`.
    if (p.kindAt(j) == kLparen() && p.kindAt(j + 1) == kIdent()
        && spanIsFill(p.src, p.startAt(j + 1), p.lenAt(j + 1))
        && p.kindAt(j + 2) == kColon()) {
      return true;
    }
    // `T[N]()` constructs only when the parentheses are empty; `arr[i](5)` is an
    // index followed by a call.
    return p.kindAt(j) == kLparen() && p.kindAt(j + 1) == kRparen();
  }
  return false;
}

/** Is this identifier span exactly `fill`? */
bool spanIsFill(u8[] s, i32 start, i32 len) {
  if (len != 4) { return false; }
  return s[start] == 'f' && s[start + 1] == 'i' && s[start + 2] == 'l' && s[start + 3] == 'l';
}

Expr parseConstructionOrCall(P p, i32 line, i32 col) {
  bool prim = identIsPrim(p, 0);
  i32 nameTok = p.advance();
  // `Vec<i32>(…)`, `Map<string, i32>.create()`, `MapEntry<K, V>?[8]()` — the one place type arguments
  // appear in something that reads like an expression, and unambiguous because what follows is a
  // construction rather than an operand. A primitive never takes them: `i32 < n` is a comparison.
  Ty[] nameArgs = prim ? Ty[]() : parseTypeArgs(p);

  // `Type.method(...)`, or `Type.method` as a funcref.
  if (p.at1(kDot())) {
    p.advance();
    i32 methodTok = -1;
    if (p.at1(kIdent())) { methodTok = p.advance(); } else { p.fail(perrMethodName()); }
    Expr base = Expr(ExprKind.Ident(nameTok), line, col);
    Expr member = Expr(ExprKind.Member(base, methodTok), line, col);
    if (p.at1(kLparen())) {
      p.advance();
      Expr[] args = parseArgList(p);
      p.expect(kRparen());
      return Expr(ExprKind.Call(member, args), line, col);
    }
    return member;
  }

  // Array construction. The element type may carry its own suffixes:
  // `i32[][3]()`, `Node?[5]()`, and its own type arguments: `MapEntry<K, V>?[8]()`.
  if (p.at1(kLbrack()) || p.at1(kQuestion())) {
    Ty elem = prim ? tyPrim(nameTok, line, col) : tyNamed(nameTok, nameArgs, line, col);
    if (p.at1(kQuestion())) {
      i32 nLine = p.lineAt(0); i32 nCol = p.colAt(0);
      p.advance();
      elem = tyNullable(elem, nLine, nCol);
    }
    while (p.at1(kLbrack()) && p.at2(kRbrack(), 1) && !p.at2(kLparen(), 2)) {
      i32 aLine = p.lineAt(0); i32 aCol = p.colAt(0);
      p.advance();
      p.advance();
      elem = tyArr(elem, aLine, aCol);
    }
    return parseArrayCtorTail(p, elem, line, col);
  }

  // `Type { field: value, ... }` — named construction.
  if (p.at1(kLbrace())) {
    p.advance();
    NamedArgList named = NamedArgList.create();
    if (!p.at1(kRbrace())) {
      while (true) {
        i32 fieldTok = -1;
        fieldTok = declName(p, perrFieldName());
        p.expect(kColon());
        named.push(NamedArg(fieldTok, parseExpr(p)));
        if (!p.eat(kComma())) { break; }
        if (p.at1(kRbrace())) { break; }         // trailing comma
      }
    }
    p.expect(kRbrace());
    Expr[] empty = Expr[]();
    return Expr(ExprKind.Construct(tyNamed(nameTok, nameArgs, line, col), empty, named.take()),
      line, col);
  }

  // `Type(args)` — positional construction.
  if (p.at1(kLparen())) {
    p.advance();
    Expr[] args = parseArgList(p);
    p.expect(kRparen());
    Ty t = prim ? tyPrim(nameTok, line, col) : tyNamed(nameTok, nameArgs, line, col);
    NamedArg[] empty = NamedArg[]();
    return Expr(ExprKind.Construct(t, args, empty), line, col);
  }

  p.fail(perrCtorBrace());
  return Expr(ExprKind.Ident(nameTok), line, col);
}

// ── Lvalues ───────────────────────────────────────────────────────────────────

/**
 * Reinterpret an expression as an assignment target, or null if it is not one.
 *
 * Used for `++`/`--`, whose operand is parsed as an expression before anyone knows
 * it needs to be an lvalue. The exhaustive `match` here is the part the node pool
 * could not check: this is precisely a conversion between two tag spaces, and it
 * used to be a chain of integer comparisons with a silent fall-through.
 */
Lvalue? exprToLvalue(Expr e) {
  match (e.kind) {
    case Ident(tok): return Lvalue(LvalueKind.LIdent(tok), e.line, e.col);
    case Member(obj, nameTok): {
      Lvalue? base = exprToLvalue(obj);
      if (base is null) { return null; }
      return Lvalue(LvalueKind.LField(base!, nameTok), e.line, e.col);
    }
    case Index(arr, index): {
      Lvalue? base = exprToLvalue(arr);
      if (base is null) { return null; }
      return Lvalue(LvalueKind.LIndex(base!, index), e.line, e.col);
    }
    case Unwrap(operand): {
      Lvalue? base = exprToLvalue(operand);
      if (base is null) { return null; }
      return Lvalue(LvalueKind.LUnwrap(base!), e.line, e.col);
    }
    else: return null;
  }
}

/** Parse an assignment target directly, for the left side of `=`. */
export Lvalue parseLvalue(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  i32 nameTok = -1;
  if (p.at1(kIdent()) || p.at1(kThis())) { nameTok = p.advance(); }
  else { p.fail(perrBadLvalue()); }
  Lvalue lv = Lvalue(LvalueKind.LIdent(nameTok), line, col);
  while (true) {
    i32 pLine = p.lineAt(0);
    i32 pCol = p.colAt(0);
    if (p.at1(kDot())) {
      p.advance();
      i32 fieldTok = -1;
      fieldTok = declName(p, perrFieldName());
      lv = Lvalue(LvalueKind.LField(lv, fieldTok), pLine, pCol);
    } else if (p.at1(kLbrack())) {
      p.advance();
      Expr idx = parseExpr(p);
      p.expect(kRbrack());
      lv = Lvalue(LvalueKind.LIndex(lv, idx), pLine, pCol);
    } else if (p.at1(kBang())) {
      p.advance();
      lv = Lvalue(LvalueKind.LUnwrap(lv), pLine, pCol);
    } else {
      return lv;
    }
  }
  return lv;
}

// ── Statements ────────────────────────────────────────────────────────────────

/** Is the current token one of the compound assignment operators? */
bool atCompoundOp(P p) {
  i32 k = p.kindAt(0);
  return k == kPlusEq() || k == kMinusEq() || k == kStarEq() || k == kSlashEq()
      || k == kPercentEq() || k == kAndEq() || k == kOrEq() || k == kCaretEq()
      || k == kShlEq() || k == kShrEq() || k == kShrUEq();
}

/**
 * Does a variable declaration start here?
 *
 * A statement beginning with an identifier is ambiguous until you know whether the
 * identifier is a type: `Point p = ...` declares, `point.x = ...` assigns. The
 * reference resolves it by scanning past type suffixes and checking for a name, and
 * this does the same.
 */
bool looksLikeVarDecl(P p) {
  i32 i = 0;
  // `const` starts a declaration, unless it is the `const this` of a method.
  if (p.kindAt(0) == kConst() && p.kindAt(1) != kThis()) { i = 1; }
  i32 k = p.kindAt(i);
  if (k == kEof()) { return false; }
  if (k == kFn()) { return true; }
  if (k != kIdent() && k != kVoid()) { return false; }
  i32 j = i + 1;
  // A type-argument list first: `Vec<i32> v = …` is a declaration, and without this the statement
  // parsed as the expression `Vec < i32` and failed at the `=`. This is where the classic C++
  // ambiguity would live, and wac gets off lightly — the scan wants a *balanced* `<…>` followed by a
  // name, so `a < b;` and `f(a < b)` are untouched. It does claim `a < b > c` as a declaration, which
  // as an expression would compare a bool, which wac rejects anyway.
  i32 afterArgs = afterTypeArgs(p, j);
  if (afterArgs > 0) { j = afterArgs; }
  while (true) {
    if (p.kindAt(j) == kLbrack() && p.kindAt(j + 1) == kRbrack()) { j += 2; }
    else if (p.kindAt(j) == kQuestion()) { j++; }
    else { break; }
  }
  if (p.kindAt(j) == kIdent()) { return true; }
  // A keyword where the name goes still looks like a declaration, but only with an `=`
  // after it — without that guard `x as i32;` reads as a declaration named `as`. The
  // reference does the same, so that `i32 match = 1;` can be told it named a keyword
  // instead of reporting a missing semicolon further down.
  i32 k = p.kindAt(j);
  return k >= kImport() && k <= kMatch() && p.kindAt(j + 1) == kAssign();
}

Stmt[] parseBlock(P p) {
  p.expect(kLbrace());
  StmtList out = StmtList.create();
  while (!p.at1(kRbrace()) && !p.at1(kEof())) { out.push(parseStatement(p)); }
  p.expect(kRbrace());
  return out.take();
}

export Stmt parseStatement(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);

  if (p.at1(kIf()))     { return parseIfStmt(p); }
  if (p.at1(kWhile()))  { return parseWhileStmt(p); }
  if (p.at1(kFor()))    { return parseForStmt(p); }
  if (p.at1(kDo()))     { return parseDoWhileStmt(p); }
  if (p.at1(kSwitch())) { return parseSwitchStmt(p); }
  if (p.at1(kMatch()))  { return parseMatchStmt(p); }

  if (p.at1(kReturn())) {
    p.advance();
    if (p.at1(kSemi())) {
      p.advance();
      return Stmt(StmtKind.Return(null), line, col);
    }
    Expr v = parseExpr(p);
    p.expect(kSemi());
    return Stmt(StmtKind.Return(v), line, col);
  }
  if (p.at1(kBreak()))    { p.advance(); p.expect(kSemi()); return Stmt(StmtKind.Break, line, col); }
  if (p.at1(kContinue())) { p.advance(); p.expect(kSemi()); return Stmt(StmtKind.Continue, line, col); }
  if (p.at1(kTrap())) {
    // Shaped like `return`: a bare `trap;` or one carrying what the host should be told.
    p.advance();
    if (p.at1(kSemi())) { p.expect(kSemi()); return Stmt(StmtKind.Trap(null), line, col); }
    Expr msg = parseExpr(p);
    p.expect(kSemi());
    return Stmt(StmtKind.Trap(msg), line, col);
  }
  if (p.at1(kLbrace()))   { return Stmt(StmtKind.Block(parseBlock(p)), line, col); }

  if (looksLikeVarDecl(p)) { return parseVarDecl(p, false); }

  // An assignment, a bare increment, or an expression statement. Which it is only
  // becomes clear after the lvalue, so the position is saved and restored — the
  // reference does the same, and `x++ * 2;` is why: that `++` is an expression.
  if (p.at1(kIdent()) || p.at1(kThis())) {
    i32 saved = p.at;
    Lvalue lv = parseLvalue(p);
    if (p.at1(kAssign())) {
      i32 op = p.advance();
      Expr rhs = parseExpr(p);
      p.expect(kSemi());
      return Stmt(StmtKind.Assign(lv, op, rhs), line, col);
    }
    if (atCompoundOp(p)) {
      i32 op = p.advance();
      Expr rhs = parseExpr(p);
      p.expect(kSemi());
      return Stmt(StmtKind.Assign(lv, op, rhs), line, col);
    }
    if ((p.at1(kInc()) || p.at1(kDec())) && p.at2(kSemi(), 1)) {
      i32 op = p.advance();
      p.expect(kSemi());
      return Stmt(StmtKind.IncrStmt(lv, op), line, col);
    }
    p.at = saved;
  }

  Expr e = parseExpr(p);
  p.expect(kSemi());
  return Stmt(StmtKind.ExprStmt(e), line, col);
}

Stmt parseVarDecl(P p, bool noSemi) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  bool isConst = p.eat(kConst());
  Ty t = parseType(p);
  i32 nameTok = -1;
  nameTok = declName(p, perrExpected());
  p.expect(kAssign());
  Expr init = parseExpr(p);
  if (!noSemi) { p.expect(kSemi()); }
  return Stmt(StmtKind.Var(t, nameTok, init, isConst), line, col);
}

/**
 * `if`, with `else if` flattened into a one-statement else body.
 *
 * The reference models the else branch as its own three-way union (absent, else-if,
 * else-block). Here an `else if` is simply an else body holding one `If` statement,
 * which is what it means; the canonical printer normalises the reference the same way
 * so the two remain comparable.
 */
Stmt parseIfStmt(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  p.advance();
  p.expect(kLparen());
  Expr cond = parseExpr(p);
  p.expect(kRparen());
  Stmt[] then = parseBlock(p);
  Stmt[] els = Stmt[]();
  if (p.eat(kElse())) {
    if (p.at1(kIf())) {
      StmtList one = StmtList.create();
      one.push(parseIfStmt(p));
      els = one.take();
    } else {
      els = parseBlock(p);
    }
  }
  return Stmt(StmtKind.If(cond, then, els), line, col);
}

Stmt parseWhileStmt(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  p.advance();
  p.expect(kLparen());
  Expr cond = parseExpr(p);
  p.expect(kRparen());
  return Stmt(StmtKind.While(cond, parseBlock(p)), line, col);
}

/** The init and update clauses of a `for` accept an assignment or an increment. */
Stmt? parseForClause(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  if (!p.at1(kIdent())) { return null; }
  Lvalue lv = parseLvalue(p);
  if (p.at1(kAssign())) {
    i32 op = p.advance();
    return Stmt(StmtKind.Assign(lv, op, parseExpr(p)), line, col);
  }
  if (atCompoundOp(p)) {
    i32 op = p.advance();
    return Stmt(StmtKind.Assign(lv, op, parseExpr(p)), line, col);
  }
  if (p.at1(kInc()) || p.at1(kDec())) {
    i32 op = p.advance();
    return Stmt(StmtKind.IncrStmt(lv, op), line, col);
  }
  p.fail(perrExpected());
  return null;
}

Stmt parseForStmt(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  p.advance();
  p.expect(kLparen());

  Stmt? init = null;
  if (!p.at1(kSemi())) {
    if (looksLikeVarDecl(p)) { init = parseVarDecl(p, true); }
    else { init = parseForClause(p); }
  }
  p.expect(kSemi());
  Expr? cond = null;
  if (!p.at1(kSemi())) { cond = parseExpr(p); }
  p.expect(kSemi());
  Stmt? update = null;
  if (!p.at1(kRparen())) { update = parseForClause(p); }
  p.expect(kRparen());
  return Stmt(StmtKind.For(init, cond, update, parseBlock(p)), line, col);
}

Stmt parseDoWhileStmt(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  p.advance();
  Stmt[] body = parseBlock(p);
  p.expect(kWhile());
  p.expect(kLparen());
  Expr cond = parseExpr(p);
  p.expect(kRparen());
  p.expect(kSemi());
  return Stmt(StmtKind.DoWhile(body, cond), line, col);
}

/** A case body, either brace-wrapped or running to the next `case`/`default`/`}`. */
Stmt[] parseSwitchBody(P p) {
  StmtList out = StmtList.create();
  if (p.at1(kLbrace())) {
    p.advance();
    while (!p.at1(kRbrace()) && !p.at1(kEof())) { out.push(parseStatement(p)); }
    p.expect(kRbrace());
    return out.take();
  }
  while (!p.at1(kCase()) && !p.at1(kDefault()) && !p.at1(kRbrace()) && !p.at1(kEof())) {
    out.push(parseStatement(p));
  }
  return out.take();
}

Stmt parseSwitchStmt(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  p.advance();
  p.expect(kLparen());
  Expr subject = parseExpr(p);
  p.expect(kRparen());
  p.expect(kLbrace());
  CaseList cases = CaseList.create();
  // **The default is last or absent.** `switch_stmt = "switch" … "{" , { case_clause } ,
  // [ default_clause ] , "}"` in `spec/spec/grammar.md`, and a `case` after it is not a switch the
  // grammar describes. Reported at the `case`, which is the token that cannot be there.
  // `spec/cases/0091`.
  bool sawDefault = false;
  while (!p.at1(kRbrace()) && !p.at1(kEof())) {
    i32 caseLine = p.lineAt(0);
    i32 caseCol = p.colAt(0);
    if (p.at1(kCase())) {
      if (sawDefault) { p.fail(perrExpected()); }
      p.advance();
      Expr v = parseExpr(p);
      p.expect(kColon());
      cases.push(Case(v, parseSwitchBody(p), caseLine, caseCol));
    } else if (p.at1(kDefault())) {
      sawDefault = true;
      p.advance();
      p.expect(kColon());
      cases.push(Case(null, parseSwitchBody(p), caseLine, caseCol));
    } else {
      p.fail(perrExpected());
      p.advance();
    }
  }
  p.expect(kRbrace());
  return Stmt(StmtKind.Switch(subject, cases.take()), line, col);
}

/** An arm body runs to the next `case`, `else` or the closing brace. */
Stmt[] parseArmBody(P p) {
  StmtList out = StmtList.create();
  while (!p.at1(kCase()) && !p.at1(kElse()) && !p.at1(kRbrace()) && !p.at1(kEof())) {
    out.push(parseStatement(p));
  }
  return out.take();
}

/**
 * `match (x) { case A(v): expr, else: expr }` in expression position.
 *
 * The same grammar as the statement, with a value per arm instead of a body, and the arms
 * comma-separated because each one is an expression. Only the statement form existed here, which is
 * why `packages/std`'s `Option<T>` could not be read at all: `T orElse(const this, T d) { return
 * match (this) { … }; }` is the shape half that file is written in.
 */
Expr parseMatchExpr(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  p.expect(kMatch());
  p.expect(kLparen());
  Expr subject = parseExpr(p);
  p.expect(kRparen());
  p.expect(kLbrace());

  ArmList arms = ArmList.create();
  while (!p.at1(kRbrace()) && !p.at1(kEof())) {
    if (p.eat(kElse())) {
      p.expect(kColon());
      arms.push(Arm(-1, i32[0](), Stmt[](), parseExpr(p)));
    } else if (p.eat(kCase())) {
      i32 variantTok = -1;
      if (p.at1(kIdent())) { variantTok = p.advance(); } else { p.fail(perrExpected()); }
      I32List bindings = I32List.create();
      if (p.eat(kLparen())) {
        if (!p.at1(kRparen())) {
          while (true) {
            if (p.at1(kRparen())) { break; }             // trailing comma
            if (p.at1(kIdent())) { bindings.push(p.advance()); } else { p.fail(perrExpected()); }
            if (!p.eat(kComma())) { break; }
          }
        }
        p.expect(kRparen());
      }
      p.expect(kColon());
      arms.push(Arm(variantTok, bindings.take(), Stmt[](), parseExpr(p)));
    } else {
      p.fail(perrExpected());
      p.advance();
      continue;
    }
    // A trailing comma after the last arm is allowed, as in every other list.
    if (!p.eat(kComma())) { break; }
  }
  p.expect(kRbrace());
  return Expr(ExprKind.MatchExpr(subject, arms.take()), line, col);
}

Stmt parseMatchStmt(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  p.expect(kMatch());
  p.expect(kLparen());
  Expr subject = parseExpr(p);
  p.expect(kRparen());
  p.expect(kLbrace());

  ArmList arms = ArmList.create();
  while (!p.at1(kRbrace()) && !p.at1(kEof())) {
    if (p.eat(kElse())) {
      p.expect(kColon());
      arms.push(Arm(-1, i32[0](), parseArmBody(p), null));
      continue;
    }
    if (!p.eat(kCase())) {
      p.fail(perrExpected());
      p.advance();
      continue;
    }
    i32 variantTok = -1;
    if (p.at1(kIdent())) { variantTok = p.advance(); } else { p.fail(perrExpected()); }
    I32List bindings = I32List.create();
    if (p.eat(kLparen())) {
      if (!p.at1(kRparen())) {
        while (true) {
          if (p.at1(kRparen())) { break; }         // trailing comma
          if (p.at1(kIdent())) { bindings.push(p.advance()); } else { p.fail(perrExpected()); }
          if (!p.eat(kComma())) { break; }
        }
      }
      p.expect(kRparen());
    }
    p.expect(kColon());
    arms.push(Arm(variantTok, bindings.take(), parseArmBody(p), null));
  }
  p.expect(kRbrace());
  return Stmt(StmtKind.Match(subject, arms.take()), line, col);
}

// ── Declarations ──────────────────────────────────────────────────────────────

void parseParams(P p, ParamList out) {
  while (true) {
    if (p.at1(kRparen())) { return; }              // trailing comma
    bool isConst = p.eat(kConst());
    Ty t = parseType(p);
    i32 nameTok = -1;
    nameTok = declName(p, perrExpected());
    out.push(Param(nameTok, t, isConst));
    if (!p.eat(kComma())) { return; }
  }
}

Decl parseImport(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  p.advance();
  p.expect(kLbrace());
  ImportItemList items = ImportItemList.create();
  while (true) {
    i32 nameTok = -1;
    if (p.at1(kIdent())) { nameTok = p.advance(); } else { p.fail(perrExpected()); }
    i32 aliasTok = nameTok;
    if (p.eat(kAs())) {
      if (p.at1(kIdent())) { aliasTok = p.advance(); } else { p.fail(perrExpected()); }
    }
    items.push(ImportItem(nameTok, aliasTok));
    if (!p.eat(kComma())) { break; }
    if (p.at1(kRbrace())) { break; }               // trailing comma
  }
  p.expect(kRbrace());
  // `from` lexes as an ordinary identifier — it stopped being a keyword so that
  // `slice(a, from, to)` could name its argument. Any identifier is taken here rather than that
  // one: only an import clause can put a word in this position, so the reference's message is the
  // one that names it, and this parser has no error code for "the wrong contextual keyword".
  if (p.at1(kIdent())) { p.advance(); } else { p.fail(perrExpected()); }
  // A quoted specifier is a path. A bare word is `core`, the module the compiler ships — it is not
  // a file, so it is not quoted, and there is nothing here to resolve it against.
  //
  // The word is recorded rather than checked, the same way `from` above is recorded rather than
  // checked. The reference rejects anything but `core`; matching that means a new error code, and
  // this parser does not yet distinguish the contextual keywords it already accepts loosely.
  i32 pathTok = -1;
  i32 prefixTok = -1;
  if (p.at1(kString())) { pathTok = p.advance(); }
  else if (p.at1(kIdent())) { prefixTok = p.advance(); }
  else { p.fail(perrExpected()); }
  p.expect(kSemi());
  return Decl(DeclKind.Import(pathTok, prefixTok, items.take()), line, col);
}

Decl parseStructDecl(P p, bool exported) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  bool isConst = p.eat(kConst());
  p.advance();                                     // struct
  i32 nameTok = -1;
  nameTok = declName(p, perrExpected());
  i32[] typeParams = parseTypeParams(p);
  i32 parentTok = -1;
  if (p.eat(kColon())) {
    if (p.at1(kIdent())) { parentTok = p.advance(); } else { p.fail(perrExpected()); }
  }
  p.expect(kLbrace());

  FieldList fields = FieldList.create();
  MethodList methods = MethodList.create();

  while (!p.at1(kRbrace()) && !p.at1(kEof())) {
    i32 overrideTok = p.at;
    bool isOverride = p.eat(kOverride());
    if (!isOverride) { overrideTok = -1; }
    // `const type name;` is a const field; `const this` is a method receiver.
    bool fieldConst = !isOverride && p.at1(kConst()) && p.kindAt(1) != kThis();
    if (fieldConst) { p.advance(); }

    Ty memberType = parseType(p);
    i32 memberTok = -1;
    memberTok = declName(p, perrExpected());

    if (p.at1(kSemi())) {
      p.advance();
      fields.push(Field(memberTok, memberType, fieldConst));
    } else if (p.at1(kLparen())) {
      p.advance();
      bool hasThis = false;
      bool thisConst = false;
      ParamList params = ParamList.create();
      if (!p.at1(kRparen())) {
        if (p.at1(kConst()) && p.kindAt(1) == kThis()) {
          thisConst = true;
          hasThis = true;
          p.advance();
          p.advance();
          if (p.eat(kComma())) { parseParams(p, params); }
        } else if (p.at1(kThis())) {
          hasThis = true;
          p.advance();
          if (p.eat(kComma())) { parseParams(p, params); }
        } else {
          parseParams(p, params);
        }
      }
      p.expect(kRparen());
      methods.push(Method(memberTok, memberType, params.take(), parseBlock(p),
        isOverride, overrideTok, hasThis, thisConst));
    } else {
      p.fail(perrExpected());
      while (!p.at1(kRbrace()) && !p.at1(kSemi()) && !p.at1(kEof())) { p.advance(); }
      p.eat(kSemi());
    }
  }
  p.expect(kRbrace());
  return Decl(DeclKind.StructDecl(nameTok, parentTok, fields.take(), methods.take(),
    exported, isConst, typeParams), line, col);
}

/**
 * `enum Name<T> { Variant, Variant(payload), … methods }`.
 *
 * Variants first, then methods — and the two are told apart by shape rather than by a keyword, because
 * a variant can never look like `type name(this, …)`. This parser had no methods at all until the
 * corpus needed them: every enum in the readable half of the corpus happens to have none, and
 * `Option<T>` — which has six — was skipped for using generics, so the gap was invisible. Both halves
 * of that are wac-mono 0003.
 */
Decl parseEnumDecl(P p, bool exported) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  p.expect(kEnum());
  i32 nameTok = -1;
  nameTok = declName(p, perrExpected());
  // As on a struct, and for the same reason: the parameters are in scope for every variant's payload
  // types and every method below.
  i32[] typeParams = parseTypeParams(p);
  p.expect(kLbrace());
  VariantList variants = VariantList.create();
  MethodList methods = MethodList.create();
  while (!p.at1(kRbrace()) && !p.at1(kEof())) {
    if (looksLikeEnumMethod(p)) { break; }
    i32 vTok = -1;
    if (p.at1(kIdent())) { vTok = p.advance(); } else { p.fail(perrExpected()); }
    ParamList fields = ParamList.create();
    if (p.eat(kLparen())) {
      if (!p.at1(kRparen())) { parseParams(p, fields); }
      p.expect(kRparen());
    }
    variants.push(Variant(vTok, fields.take()));
    if (!p.eat(kComma())) { break; }
  }

  while (!p.at1(kRbrace()) && !p.at1(kEof())) {
    // `override` means nothing here — the variants are the compiler's own subtypes, so an override
    // would be per-variant dispatch, a different feature. Refused rather than quietly accepted.
    if (p.at1(kOverride())) {
      p.fail(perrExpected());
      p.advance();
    }
    Ty returnType = parseType(p);
    i32 mTok = -1;
    if (p.at1(kIdent())) { mTok = p.advance(); } else { p.fail(perrMethodName()); }
    p.expect(kLparen());
    bool hasThis = false;
    bool thisConst = false;
    ParamList params = ParamList.create();
    if (!p.at1(kRparen())) {
      if (p.at1(kConst()) && p.kindAt(1) == kThis()) {
        thisConst = true;
        hasThis = true;
        p.advance();
        p.advance();
        if (p.eat(kComma())) { parseParams(p, params); }
      } else if (p.at1(kThis())) {
        hasThis = true;
        p.advance();
        if (p.eat(kComma())) { parseParams(p, params); }
      } else {
        parseParams(p, params);
      }
    }
    p.expect(kRparen());
    // A static method would be spelled `Shape.make()`, which is already how a variant is constructed,
    // so one is refused until that ambiguity is decided deliberately.
    if (!hasThis) { p.fail(perrMethodName()); }
    methods.push(Method(mTok, returnType, params.take(), parseBlock(p), false, -1, hasThis, thisConst));
  }

  p.expect(kRbrace());
  return Decl(DeclKind.EnumDecl(nameTok, variants.take(), exported, methods.take(), typeParams),
    line, col);
}

/**
 * Does a method start here, rather than another variant?
 *
 * A variant is `IDENT` or `IDENT(…)`; a method is a *type* followed by a name and a parameter list. So
 * the question is what follows the first identifier — another identifier and a `(` is a method, and
 * anything else is a variant. `override`, `void` and `fn` can only begin a method.
 */
bool looksLikeEnumMethod(P p) {
  if (p.at1(kOverride()) || p.at1(kVoid()) || p.at1(kFn())) { return true; }
  if (!p.at1(kIdent())) { return false; }
  i32 j = 1;
  // The type's own suffixes: `i32[] name(…)`, `Node? name(…)`.
  while (true) {
    if (p.kindAt(j) == kLbrack() && p.kindAt(j + 1) == kRbrack()) { j += 2; }
    else if (p.kindAt(j) == kQuestion()) { j++; }
    else { break; }
  }
  return p.kindAt(j) == kIdent() && p.kindAt(j + 1) == kLparen();
}

Decl parseFuncDecl(P p) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  bool exported = p.eat(kExport());
  Ty ret = parseType(p);
  i32 nameTok = -1;
  nameTok = declName(p, perrExpected());
  i32[] typeParams = parseTypeParams(p);
  p.expect(kLparen());
  ParamList params = ParamList.create();
  if (!p.at1(kRparen())) { parseParams(p, params); }
  p.expect(kRparen());
  return Decl(DeclKind.Func(nameTok, ret, params.take(), parseBlock(p), exported,
    typeParams), line, col);
}

Decl parseConstDecl(P p, bool exported) {
  i32 line = p.lineAt(0);
  i32 col = p.colAt(0);
  p.expect(kConst());
  Ty t = parseType(p);
  i32 nameTok = -1;
  if (p.at1(kIdent())) { nameTok = p.advance(); } else { p.fail(perrExpected()); }
  p.expect(kAssign());
  Expr init = parseExpr(p);
  p.expect(kSemi());
  return Decl(DeclKind.ConstDecl(nameTok, t, init, exported), line, col);
}

/** The whole file. */
export Program parseProgram(P p) {
  DeclList decls = DeclList.create();
  while (!p.at1(kEof())) {
    if (p.at1(kImport())) { decls.push(parseImport(p)); continue; }

    // `export` may precede a struct, an enum, a const or a function, and the
    // declaration kind is only known after it.
    bool exported = p.at1(kExport());
    i32 after = exported ? 1 : 0;
    i32 k = p.kindAt(after);
    if (k == kStruct() || (k == kConst() && p.kindAt(after + 1) == kStruct())) {
      if (exported) { p.advance(); }
      decls.push(parseStructDecl(p, exported));
    } else if (k == kEnum()) {
      if (exported) { p.advance(); }
      decls.push(parseEnumDecl(p, exported));
    } else if (k == kConst()) {
      if (exported) { p.advance(); }
      decls.push(parseConstDecl(p, exported));
    } else if (exported || k == kFn() || k == kVoid() || k == kIdent()) {
      // A function: `parseFuncDecl` consumes its own `export`. Entered only when the
      // token could actually begin one — a return type is an `ident` (the primitives
      // are not keywords), or `void`, or `fn`, or an `export` whose declaration kind
      // was not matched above.
      i32 before = p.at;
      decls.push(parseFuncDecl(p));
      if (p.at == before) {
        // No progress — a malformed top-level construct. Skip a token so the loop
        // cannot spin, and let the error already recorded stand.
        p.fail(perrTopLevel());
        p.advance();
      }
    } else {
      // Nothing can start a top-level item here. One error and skip the token, which
      // is what the reference does; attempting a function parse instead makes the
      // parser report a cascade of missing types and names for what is really a single
      // stray token. `;;;` produced eleven errors that way against the reference's
      // three, and a stray `}` after a complete function produced seven against one.
      p.fail(perrTopLevel());
      p.advance();
    }
  }
  return Program(decls.take());
}
// A canonical text form for the AST, so it can be compared against the reference.
//
// The oracle for the parser is the TypeScript implementation, and the two build
// unrelated data structures — one an object graph with string fields, the other sum
// types holding token indices. Comparing them means projecting both onto one text
// form, and this is that form. `test/parse.test.ts` produces the same text from the
// reference AST.
//
// Shape: `(kind@line:col child child ...)`. Positions are included because they are
// part of what the parser is responsible for, and rung 3's diagnostics compare by
// position — so a divergence is worth catching here rather than one rung later.
//
// Every walk here is a `match` over an AST enum, so adding a variant breaks this file
// at compile time. That is the whole reason the AST is sum types: this printer is the
// exact shape of code the node pool made unsafe, a dispatch on tag where nothing
// checked that the fields being read meant what the tag implied.

import { Buf } from "../../bytes/src/buf.wac";
import { Ty, TyKind, Expr, ExprKind, NamedArg, Lvalue, LvalueKind,
  Stmt, StmtKind, Case, Arm,
  Decl, DeclKind, Param, Field, Method, Variant, ImportItem, Program } from "./ast.wac";
import { tokenStride } from "./lex.wac";

/** Everything the printer needs: the AST's token table and the source behind it. */
export struct Pr {
  Buf out;
  u8[] src;
  i32[] toks;
  i32 tokCount;

  Pr create(u8[] src, i32[] toks, i32 tokCount) {
    return Pr(Buf.withCapacity(4096), src, toks, tokCount);
  }

  void s(this, string text) { this.out.pushAll(text.toBytes()); }

  void num(this, i32 v) {
    if (v < 0) { this.out.push('-'); this.num(0 - v); return; }
    if (v >= 10) { this.num(v / 10); }
    this.out.push('0' + v % 10);
  }

  /** `@line:col`, the position suffix every node carries. */
  void pos(this, i32 line, i32 col) {
    this.out.push('@');
    this.num(line);
    this.out.push(':');
    this.num(col);
  }

  void open(this, string kind, i32 line, i32 col) {
    this.out.push('(');
    this.s(kind);
    this.pos(line, col);
  }

  void close(this) { this.out.push(')'); }
  void sp(this) { this.out.push(' '); }

  /**
   * The raw source text of a token.
   *
   * A token index of -1 means the parser recorded an error and had no name to use;
   * it prints as `?`, which is what the reference substitutes in the same situation.
   */
  void tok(this, i32 t) {
    if (t < 0 || t >= this.tokCount) { this.out.push('?'); return; }
    i32 start = this.toks[t * tokenStride() + 1];
    i32 len = this.toks[t * tokenStride() + 2];
    for (i32 i = 0; i < len; i++) { this.out.push(this.src[start + i]); }
  }

  /**
   * An integer literal token, as the reference stores it.
   *
   * A character literal is an `int` token whose value is its codepoint, so `'a'`
   * prints as `97` rather than as its span. Every other number prints verbatim,
   * including its underscores and hex prefix, because that is what the reference
   * keeps.
   */
  void intTok(this, i32 t) {
    if (t < 0 || t >= this.tokCount) { this.out.push('?'); return; }
    i32 start = this.toks[t * tokenStride() + 1];
    i32 len = this.toks[t * tokenStride() + 2];
    if (len == 0 || this.src[start] != '\'') { this.tok(t); return; }
    this.num(charLitValue(this.src, start, len));
  }

  /**
   * A string literal token, unescaped and then re-escaped canonically.
   *
   * The reference stores the *unescaped* value, so the span cannot be compared
   * directly: `"a\nb"` is three characters there and six bytes here. Both sides
   * unescape and then re-escape by the same rule, which makes the comparison exact
   * without either side having to reproduce the other's quoting.
   */
  void strTok(this, i32 t) {
    if (t < 0 || t >= this.tokCount) { this.out.push('?'); return; }
    i32 start = this.toks[t * tokenStride() + 1];
    i32 len = this.toks[t * tokenStride() + 2];
    this.out.push('"');
    // Skip the opening quote, and the closing one when the literal is terminated.
    i32 i = start + 1;
    i32 end = start + len;
    if (len > 1 && this.src[end - 1] == '"') { end = end - 1; }
    while (i < end) {
      i32 c = this.src[i];
      if (c == '\\' && i + 1 < end) {
        i32 e = this.src[i + 1];
        i += 2;
        if (e == 'n')       { this.escByte(10); }
        else if (e == 't')  { this.escByte(9); }
        else if (e == 'r')  { this.escByte(13); }
        else if (e == '\\') { this.escByte('\\'); }
        else if (e == '"')  { this.escByte('"'); }
        else if (e == '0')  { this.escByte(0); }
        else { this.escByte(e); }        // an unknown escape keeps the character
        continue;
      }
      this.escByte(c);
      i++;
    }
    this.out.push('"');
  }

  /** One byte of a string, escaped so the result is unambiguous and printable. */
  void escByte(this, i32 c) {
    if (c == '\\' || c == '"') { this.out.push('\\'); this.out.push(c); return; }
    if (c < 32 || c == 127) {
      this.out.push('\\');
      this.out.push('x');
      this.out.push(hexDigit(c >> 4));
      this.out.push(hexDigit(c & 15));
      return;
    }
    this.out.push(c);
  }
}

i32 hexDigit(i32 v) { return v < 10 ? '0' + v : 'a' + (v - 10); }

/** The codepoint a character literal denotes, given its raw span. */
i32 charLitValue(u8[] s, i32 start, i32 len) {
  i32 end = start + len;
  if (len > 1 && s[end - 1] == '\'') { end = end - 1; }
  i32 i = start + 1;
  if (i >= end) { return 0; }
  if (s[i] == '\\' && i + 1 < end) {
    i32 e = s[i + 1];
    if (e == 'n')  { return 10; }
    if (e == 't')  { return 9; }
    if (e == 'r')  { return 13; }
    if (e == '\\') { return 92; }
    if (e == '"')  { return 34; }
    if (e == '\'') { return 39; }
    if (e == '0')  { return 0; }
    return e;
  }
  // A literal character, decoded from UTF-8 so a non-ASCII one gives its codepoint.
  i32 c = s[i];
  if (c < 0x80) { return c; }
  if ((c & 0xE0) == 0xC0 && i + 1 < end) {
    return ((c & 0x1F) << 6) | (s[i + 1] & 0x3F);
  }
  if ((c & 0xF0) == 0xE0 && i + 2 < end) {
    return ((c & 0x0F) << 12) | ((s[i + 1] & 0x3F) << 6) | (s[i + 2] & 0x3F);
  }
  if ((c & 0xF8) == 0xF0 && i + 3 < end) {
    return ((c & 0x07) << 18) | ((s[i + 1] & 0x3F) << 12)
         | ((s[i + 2] & 0x3F) << 6) | (s[i + 3] & 0x3F);
  }
  return c;
}

// ── Types ─────────────────────────────────────────────────────────────────────

void printTy(Pr w, Ty t) {
  match (t.kind) {
    case Prim(tok): {
      w.open("prim", t.line, t.col);
      w.sp();
      // No token means the parser substituted `i32` for a malformed type, which is
      // exactly what the reference does, so it prints as that rather than as `?`.
      if (tok < 0) { w.s("i32"); } else { w.tok(tok); }
      w.close();
    }
    case Named(tok, typeArgs): {
      w.open("named", t.line, t.col);
      w.sp();
      w.tok(tok);
      // The argument list is always printed, empty or not: one shape for `Vec<i32>` and for `Node`
      // means the two sides of the differential cannot agree by both omitting something.
      w.s(" (");
      for (i32 i = 0; i < typeArgs.len(); i++) {
        if (i > 0) { w.sp(); }
        printTy(w, typeArgs[i]);
      }
      w.out.push(')');
      w.close();
    }
    case Arr(elem): {
      w.open("arr", t.line, t.col);
      w.sp();
      printTy(w, elem);
      w.close();
    }
    case Nullable(inner): {
      w.open("nullable", t.line, t.col);
      w.sp();
      printTy(w, inner);
      w.close();
    }
    case Funcref(ret, params): {
      w.open("funcref", t.line, t.col);
      w.sp();
      printTy(w, ret);
      w.s(" (");
      for (i32 i = 0; i < params.len(); i++) {
        if (i > 0) { w.sp(); }
        printTy(w, params[i]);
      }
      w.s("))");
    }
  }
}

// ── Expressions ───────────────────────────────────────────────────────────────

void printExpr(Pr w, Expr e) {
  match (e.kind) {
    case IntLit(tok): {
      w.open("int", e.line, e.col); w.sp(); w.intTok(tok); w.close();
    }
    case FloatLit(tok): {
      w.open("float", e.line, e.col); w.sp(); w.tok(tok); w.close();
    }
    case StrLit(tok): {
      w.open("str", e.line, e.col); w.sp(); w.strTok(tok); w.close();
    }
    case BoolLit(value): {
      w.open("bool", e.line, e.col);
      w.sp();
      w.s(value ? "true" : "false");
      w.close();
    }
    case NullLit: {
      w.open("null", e.line, e.col); w.close();
    }
    case Ident(tok): {
      w.open("ident", e.line, e.col); w.sp(); w.tok(tok); w.close();
    }
    case Unary(op, operand): {
      w.open("unary", e.line, e.col);
      w.sp(); w.tok(op);
      w.sp(); printExpr(w, operand);
      w.close();
    }
    case Binary(op, left, right): {
      w.open("binary", e.line, e.col);
      w.sp(); w.tok(op);
      w.sp(); printExpr(w, left);
      w.sp(); printExpr(w, right);
      w.close();
    }
    case Cast(op, operand, target): {
      w.open("cast", e.line, e.col);
      w.sp(); w.tok(op);
      w.sp(); printExpr(w, operand);
      w.sp(); printTy(w, target);
      w.close();
    }
    case Is(left, target, other, negated): {
      w.open("is", e.line, e.col);
      w.sp(); w.s(negated ? "not" : "plain");
      w.sp(); printExpr(w, left);
      w.sp();
      // A type prints as `(prim ...)`/`(named ...)` and a value as `(ident ...)`, so
      // the three forms stay distinguishable without a tag of their own.
      if (target is not null)     { printTy(w, target!); }
      else if (other is not null) { printExpr(w, other!); }
      else                        { w.s("null"); }
      w.close();
    }
    // A `match` in expression position: an arm has a value where the statement's has a body.
    case MatchExpr(subject, arms): {
      w.open("matchexpr", e.line, e.col);
      w.sp(); printExpr(w, subject);
      w.s(" (");
      for (i32 i = 0; i < arms.len(); i++) {
        if (i > 0) { w.sp(); }
        w.s("(arm ");
        if (arms[i].variantTok < 0) { w.s("else"); } else { w.tok(arms[i].variantTok); }
        w.s(" (");
        for (i32 j = 0; j < arms[i].bindingToks.len(); j++) {
          if (j > 0) { w.sp(); }
          w.tok(arms[i].bindingToks[j]);
        }
        w.out.push(')');
        w.sp();
        printExpr(w, arms[i].value!);
        w.out.push(')');
      }
      w.s("))");
    }
    case Ternary(cond, then, els): {
      w.open("ternary", e.line, e.col);
      w.sp(); printExpr(w, cond);
      w.sp(); printExpr(w, then);
      w.sp(); printExpr(w, els);
      w.close();
    }
    case Call(callee, args): {
      w.open("call", e.line, e.col);
      w.sp(); printExpr(w, callee);
      printExprList(w, args);
      w.close();
    }
    case Index(arr, index): {
      w.open("index", e.line, e.col);
      w.sp(); printExpr(w, arr);
      w.sp(); printExpr(w, index);
      w.close();
    }
    case Member(obj, nameTok): {
      w.open("member", e.line, e.col);
      w.sp(); printExpr(w, obj);
      w.sp(); w.tok(nameTok);
      w.close();
    }
    case Unwrap(operand): {
      w.open("unwrap", e.line, e.col);
      w.sp(); printExpr(w, operand);
      w.close();
    }
    case Construct(ctype, args, named): {
      w.open("construct", e.line, e.col);
      w.sp(); printTy(w, ctype);
      printExprList(w, args);
      w.s(" (");
      for (i32 i = 0; i < named.len(); i++) {
        if (i > 0) { w.sp(); }
        w.out.push('(');
        w.tok(named[i].nameTok);
        w.sp();
        printExpr(w, named[i].value);
        w.out.push(')');
      }
      w.s("))");
    }
    case Incr(target, op, prefix): {
      w.open("incr", e.line, e.col);
      w.sp(); w.tok(op);
      w.sp(); w.s(prefix ? "pre" : "post");
      w.sp(); printLvalue(w, target);
      w.close();
    }
    case ArrNew(elem, size, fill, elements): {
      w.open("arrnew", e.line, e.col);
      w.sp(); printTy(w, elem);
      w.sp();
      if (size is null) { w.s("-"); } else { printExpr(w, size!); }
      w.sp();
      if (fill is null) { w.s("-"); } else { printExpr(w, fill!); }
      printExprList(w, elements);
      w.close();
    }
  }
}

void printExprList(Pr w, Expr[] items) {
  w.s(" (");
  for (i32 i = 0; i < items.len(); i++) {
    if (i > 0) { w.sp(); }
    printExpr(w, items[i]);
  }
  w.out.push(')');
}

// ── Lvalues ───────────────────────────────────────────────────────────────────

void printLvalue(Pr w, Lvalue lv) {
  match (lv.kind) {
    case LIdent(tok): {
      w.open("lv-ident", lv.line, lv.col); w.sp(); w.tok(tok); w.close();
    }
    case LField(base, nameTok): {
      w.open("lv-field", lv.line, lv.col);
      w.sp(); printLvalue(w, base);
      w.sp(); w.tok(nameTok);
      w.close();
    }
    case LIndex(base, index): {
      w.open("lv-index", lv.line, lv.col);
      w.sp(); printLvalue(w, base);
      w.sp(); printExpr(w, index);
      w.close();
    }
    case LUnwrap(base): {
      w.open("lv-unwrap", lv.line, lv.col);
      w.sp(); printLvalue(w, base);
      w.close();
    }
  }
}

// ── Statements ────────────────────────────────────────────────────────────────

void printStmt(Pr w, Stmt s) {
  match (s.kind) {
    case Var(type, nameTok, init, isConst): {
      w.open("var", s.line, s.col);
      w.sp(); w.s(isConst ? "const" : "let");
      w.sp(); printTy(w, type);
      w.sp(); w.tok(nameTok);
      w.sp(); printExpr(w, init);
      w.close();
    }
    case Assign(target, op, rhs): {
      w.open("assign", s.line, s.col);
      w.sp(); w.tok(op);
      w.sp(); printLvalue(w, target);
      w.sp(); printExpr(w, rhs);
      w.close();
    }
    case IncrStmt(target, op): {
      w.open("incr-stmt", s.line, s.col);
      w.sp(); w.tok(op);
      w.sp(); printLvalue(w, target);
      w.close();
    }
    case If(cond, then, els): {
      w.open("if", s.line, s.col);
      w.sp(); printExpr(w, cond);
      printStmtList(w, then);
      printStmtList(w, els);
      w.close();
    }
    case While(cond, body): {
      w.open("while", s.line, s.col);
      w.sp(); printExpr(w, cond);
      printStmtList(w, body);
      w.close();
    }
    case For(init, cond, update, body): {
      w.open("for", s.line, s.col);
      w.sp();
      if (init is null) { w.s("-"); } else { printStmt(w, init!); }
      w.sp();
      if (cond is null) { w.s("-"); } else { printExpr(w, cond!); }
      w.sp();
      if (update is null) { w.s("-"); } else { printStmt(w, update!); }
      printStmtList(w, body);
      w.close();
    }
    case DoWhile(body, cond): {
      w.open("dowhile", s.line, s.col);
      printStmtList(w, body);
      w.sp(); printExpr(w, cond);
      w.close();
    }
    case Switch(subject, cases): {
      w.open("switch", s.line, s.col);
      w.sp(); printExpr(w, subject);
      w.s(" (");
      for (i32 i = 0; i < cases.len(); i++) {
        if (i > 0) { w.sp(); }
        w.s("(case ");
        if (cases[i].value is null) { w.s("default"); } else { printExpr(w, cases[i].value!); }
        printStmtList(w, cases[i].body);
        w.out.push(')');
      }
      w.s("))");
    }
    case Match(subject, arms): {
      w.open("match", s.line, s.col);
      w.sp(); printExpr(w, subject);
      w.s(" (");
      for (i32 i = 0; i < arms.len(); i++) {
        if (i > 0) { w.sp(); }
        w.s("(arm ");
        if (arms[i].variantTok < 0) { w.s("else"); } else { w.tok(arms[i].variantTok); }
        w.s(" (");
        for (i32 j = 0; j < arms[i].bindingToks.len(); j++) {
          if (j > 0) { w.sp(); }
          w.tok(arms[i].bindingToks[j]);
        }
        w.out.push(')');
        printStmtList(w, arms[i].body);
        w.out.push(')');
      }
      w.s("))");
    }
    case Return(value): {
      w.open("return", s.line, s.col);
      w.sp();
      if (value is null) { w.s("-"); } else { printExpr(w, value!); }
      w.close();
    }
    case Break:    { w.open("break", s.line, s.col); w.close(); }
    case Continue: { w.open("continue", s.line, s.col); w.close(); }
    case Trap(value): {
      w.open("trap", s.line, s.col);
      w.sp();
      if (value is null) { w.s("-"); } else { printExpr(w, value!); }
      w.close();
    }
    case Block(body): {
      w.open("block", s.line, s.col);
      printStmtList(w, body);
      w.close();
    }
    case ExprStmt(expr): {
      w.open("expr", s.line, s.col);
      w.sp(); printExpr(w, expr);
      w.close();
    }
  }
}

void printStmtList(Pr w, Stmt[] items) {
  w.s(" (");
  for (i32 i = 0; i < items.len(); i++) {
    if (i > 0) { w.sp(); }
    printStmt(w, items[i]);
  }
  w.out.push(')');
}

// ── Declarations ──────────────────────────────────────────────────────────────

/**
 * ` <T U>` after a declaration's name, and ` <>` when it has none.
 *
 * Always printed, for the same reason the type-argument list is: a shape that disappears when it is
 * empty lets two implementations agree by both leaving it out.
 */
void printTypeParams(Pr w, i32[] params) {
  w.s(" <");
  for (i32 i = 0; i < params.len(); i++) {
    if (i > 0) { w.sp(); }
    w.tok(params[i]);
  }
  w.out.push('>');
}

void printParams(Pr w, Param[] params) {
  w.s(" (");
  for (i32 i = 0; i < params.len(); i++) {
    if (i > 0) { w.sp(); }
    w.out.push('(');
    w.s(params[i].isConst ? "const " : "mut ");
    w.tok(params[i].nameTok);
    w.sp();
    printTy(w, params[i].type);
    w.out.push(')');
  }
  w.out.push(')');
}

void printDecl(Pr w, Decl d) {
  match (d.kind) {
    case Import(pathTok, prefixTok, items): {
      w.open("import", d.line, d.col);
      // A prefixed import has no path token, and the module *inside* the provider is the empty
      // string — `from core` names its only one. That is a value, not an absence, so it prints as
      // `""` rather than as the `?` a missing token would give.
      w.sp();
      if (pathTok < 0 && prefixTok >= 0) { w.s("\"\""); } else { w.strTok(pathTok); }
      // The provider prefix, or `-` for an ordinary path import. Printed rather than left out
      // because the differential compares these strings: without it `from core` and `from ""`
      // would render alike, and the corpus would agree about something it had not checked.
      w.sp();
      if (prefixTok < 0) { w.s("-"); } else { w.tok(prefixTok); }
      w.s(" (");
      for (i32 i = 0; i < items.len(); i++) {
        if (i > 0) { w.sp(); }
        w.out.push('(');
        w.tok(items[i].nameTok);
        w.sp();
        w.tok(items[i].aliasTok);
        w.out.push(')');
      }
      w.s("))");
    }
    case Func(nameTok, returnType, params, body, exported, typeParams): {
      w.open("func", d.line, d.col);
      w.sp(); w.s(exported ? "export" : "local");
      w.sp(); w.tok(nameTok);
      printTypeParams(w, typeParams);
      w.sp(); printTy(w, returnType);
      printParams(w, params);
      printStmtList(w, body);
      w.close();
    }
    case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
      w.open("struct", d.line, d.col);
      w.sp(); w.s(exported ? "export" : "local");
      w.sp(); w.s(isConst ? "const" : "mut");
      w.sp(); w.tok(nameTok);
      printTypeParams(w, typeParams);
      w.sp();
      if (parentTok < 0) { w.s("-"); } else { w.tok(parentTok); }
      w.s(" (");
      for (i32 i = 0; i < fields.len(); i++) {
        if (i > 0) { w.sp(); }
        w.s("(field ");
        w.s(fields[i].isConst ? "const " : "mut ");
        w.tok(fields[i].nameTok);
        w.sp();
        printTy(w, fields[i].type);
        w.out.push(')');
      }
      w.s(") (");
      for (i32 i = 0; i < methods.len(); i++) {
        if (i > 0) { w.sp(); }
        w.s("(method ");
        w.tok(methods[i].nameTok);
        w.sp();
        w.s(methods[i].isOverride ? "override" : "plain");
        w.sp();
        w.s(methods[i].hasThis ? (methods[i].thisConst ? "constthis" : "this") : "static");
        w.sp();
        printTy(w, methods[i].returnType);
        printParams(w, methods[i].params);
        printStmtList(w, methods[i].body);
        w.out.push(')');
      }
      w.s("))");
    }
    // Methods are held by the AST and *not* printed, which is what the reference does too — an enum's
    // methods are compared through rung 3's diagnostics rather than here.
    case EnumDecl(nameTok, variants, exported, methods, typeParams): {
      w.open("enum", d.line, d.col);
      w.sp(); w.s(exported ? "export" : "local");
      w.sp(); w.tok(nameTok);
      printTypeParams(w, typeParams);
      w.s(" (");
      for (i32 i = 0; i < variants.len(); i++) {
        if (i > 0) { w.sp(); }
        w.s("(variant ");
        w.tok(variants[i].nameTok);
        printParams(w, variants[i].fields);
        w.out.push(')');
      }
      w.s("))");
    }
    case ConstDecl(nameTok, type, init, exported): {
      w.open("const", d.line, d.col);
      w.sp(); w.s(exported ? "export" : "local");
      w.sp(); w.tok(nameTok);
      w.sp(); printTy(w, type);
      w.sp(); printExpr(w, init);
      w.close();
    }
  }
}

export string printProgram(Pr w, Program prog) {
  w.s("(program");
  for (i32 i = 0; i < prog.decls.len(); i++) {
    w.s("\n  ");
    printDecl(w, prog.decls[i]);
  }
  w.s(")\n");
  return w.out.toStr();
}
